// Per-request prompt fingerprint: short hashes of the cacheable prefix and the
// named pi sub-blocks. Diverging hashes across same-cwd siblings = anchor split.
function computePromptFingerprint(params) {
  if (!FINGERPRINT) return undefined;
  try {
    const systemText = collectSystemText(params);
    const fp = {
      system: shortHash(systemText),
      tools: shortHash(Array.isArray(params?.tools) ? stableStringify(params.tools) : null),
    };
    for (const { name, open, close } of FINGERPRINT_SECTIONS) {
      fp[name] = shortHash(sectionText(systemText, open, close));
    }
    return fp;
  } catch {
    return undefined;
  }
}

function pruneCallerEvents(now = Date.now()) {
  const maxWindow = Math.max(...Object.values(CALLER_WINDOWS));
  stats.callerEvents = stats.callerEvents.filter((event) => now - event.time <= maxWindow);
}

function recordCallerUsage({ meta, model, usage, requestId, statusCode, messageCount, toolCount }) {
  const now = Date.now();
  pruneCallerEvents(now);
  stats.callerEvents.push({
    time: now,
    id: callerId(meta),
    requestId,
    model,
    statusCode,
    messageCount,
    toolCount,
    meta: compactMeta(meta),
    usage: numberUsage(usage),
  });
}

function summarizeCallers(windowMs, now = Date.now()) {
  pruneCallerEvents(now);
  const callers = new Map();
  for (const event of stats.callerEvents) {
    if (now - event.time > windowMs) continue;
    const current = callers.get(event.id) ?? {
      id: event.id,
      requests: 0,
      input: 0,
      cacheRead: 0,
      cacheWrite: 0,
      lastRequest: null,
      lastRequestId: null,
      models: {},
      meta: event.meta,
    };
    current.requests += 1;
    current.input += event.usage.input;
    current.cacheRead += event.usage.cacheRead;
    current.cacheWrite += event.usage.cacheWrite;
    current.lastRequest = new Date(event.time).toISOString();
    current.lastRequestId = event.requestId;
    current.models[event.model] = (current.models[event.model] ?? 0) + 1;
    current.meta = { ...current.meta, ...event.meta };
    callers.set(event.id, current);
  }
  return [...callers.values()].sort(
    (a, b) => (b.input + b.cacheRead + b.cacheWrite) - (a.input + a.cacheRead + a.cacheWrite),
  );
}

function topCallersSnapshot() {
  const now = Date.now();
  return Object.fromEntries(
    Object.entries(CALLER_WINDOWS).map(([name, ms]) => [name, summarizeCallers(ms, now)]),
  );
}

// --- Usage extraction helpers ---

/**
 * Pull the final `usage` object out of a non-streaming JSON response body.
 * Returns null if the body isn't JSON or has no usage field.
 */
function extractJSONUsage(body) {
  try {
    const parsed = JSON.parse(body);
    const usage = parsed?.usage ?? null;
    if (usage && parsed?.diagnostics) usage.diagnostics = parsed.diagnostics;
    return usage;

