17	const INJECT_MARKER = "<!-- pi-memory:v2 -->";
18	export default function piMemoryExtension(pi: ExtensionAPI): void {
19		let slug = "unnamed";
20		let originSessionId = "";
21		let injectedSection = "";
22		const journal = newJournalState();
23		// Turn counter for Path B cursor. We deliberately do NOT retain the full
24		// AgentMessage[] history — pi already keeps it, and storing it here grew the
25		// process to OOM on long sessions with large tool-result payloads.
26		let turnCount = 0;
27		let extractor: Extractor | undefined;
28		const writesThisTurn = new Map<string, "write" | "edit">();
29		// v3: pollution counter — transient-context tools (web_search, mcp_*) flagged here.
30		const pollution = newPollutionState();
31	
32		pi.on("session_start", async (_e, ctx) => {
33			// Sub-agent guard: skip slug resolution and save-prompt construction.
34			// `ctx.source === "child-agent"` is set by pi for in-process delegated
35			// runs and out-of-process `pi --source child-agent` spawns — nothing in
36			// this extension should fire on their lifecycle.
37			if (isMemorySubAgentCtx(ctx)) return;
38			const sessionCwd = ctx.cwd;
39			const sessionId = ctx.sessionManager.getSessionId();
40			try {
41				slug = await resolveProjectSlug(sessionCwd);
42			} catch (err) {
43				console.error("[pi-memory] slug resolution failed:", err);
44			}
45			originSessionId = sessionId;
46			injectedSection = `${INJECT_MARKER}\n${buildParentMemoryPromptSection(slug, originSessionId)}`;
47		});
48	
