112	 */
113	const STABLE_EXTRACTOR_SYSTEM_PROMPT: string = loadPrompt("extractor-stable-system.md");
114	export function buildStableExtractorSystemPrompt(): string {
115		return STABLE_EXTRACTOR_SYSTEM_PROMPT;
116	}
