143	export function buildExtractPrompt(o: { newMessageCount: number; existingMemories: string; slug: string; originSessionId: string }): string {
144		const block = o.existingMemories.trim()
145			? `## Existing memory files\n\n${o.existingMemories.trim()}\n\nCheck this list before writing — update an existing file rather than creating a duplicate.`
146			: "";
