148	}
149	
150	export interface JournalState {
151		userMsgCount: number;
152		assistantMsgCount: number;
153		toolCounts: Map<string, number>;
154		fileEditCounts: Map<string, number>;
155		firstUser: string | undefined;
156		lastAssistant: string | undefined;
157		memoryWrittenThisSession: boolean;
158	}
159	export const newJournalState = (): JournalState => ({
160		userMsgCount: 0,
161		assistantMsgCount: 0,
162		toolCounts: new Map(),
163		fileEditCounts: new Map(),
164		firstUser: undefined,
165		lastAssistant: undefined,
166		memoryWrittenThisSession: false,
167	});
168	/** ≥2 user msgs OR ≥1 tool call, AND no memory write this session (mutex). */
169	export function isSubstantive(s: JournalState): boolean {
170		if (s.memoryWrittenThisSession) return false;
171		if (s.userMsgCount >= 2) return true;
172		let t = 0;
173		for (const n of s.toolCounts.values()) t += n;
174		return t >= 1;
175	}
176	const trim1 = (s: string | undefined, max = 200): string => {
177		const f = (s ?? "").replace(/\s+/g, " ").trim();
178		return f.length > max ? `${f.slice(0, max - 1)}…` : f;
179	};
180	export function renderJournalEntry(s: JournalState, i: { sessionId: string; slug: string; now?: Date }): string {
181		const ts = (i.now ?? new Date()).toISOString().replace(/\.\d+Z$/, "Z");
182		const sortByCount = <T>(m: Map<T, number>) => [...m].sort((a, b) => b[1] - a[1]);
183		const tools = sortByCount(s.toolCounts)
184			.map(([n, c]) => `${n}×${c}`)
185			.join(", ");
186		const files = sortByCount(s.fileEditCounts)
187			.slice(0, 5)
188			.map(([f]) => f);
189		const out = [`## ${ts} [sid:${i.sessionId}]`, `- cwd: ${i.slug}`, `- msgs: ${s.userMsgCount} user / ${s.assistantMsgCount} assistant`];
190		if (tools) out.push(`- tools: ${tools}`);
191		if (files.length) out.push(`- files: ${files.join(", ")}`);
192		if (s.firstUser) out.push(`- first_user: "${trim1(s.firstUser)}"`);
193		if (s.lastAssistant) out.push(`- last_assistant: "${trim1(s.lastAssistant)}"`);
194		return `${out.join("\n")}\n\n`;
195	}
196	export function appendJournal(entry: string, now: Date = new Date()): string {
197		const d = journalDir();
198		if (!existsSync(d)) mkdirSync(d, { recursive: true });
199		const file = join(d, `${now.toISOString().slice(0, 10)}.md`);
200		appendFileSync(file, entry, "utf8");
201		return file;
202	}
203	
204	function snapshot(slug: string): Map<string, number> {
205		const out = new Map<string, number>();
206		const walk = (d: string, left: number): void => {
207			if (!existsSync(d)) return;
208			for (const e of readdirSync(d)) {
209				const f = join(d, e);
210				try {
211					const st = statSync(f);
212					if (st.isDirectory() && left > 0) walk(f, left - 1);
213					else if (st.isFile() && e.endsWith(".md")) out.set(f, st.mtimeMs);
214				} catch {}
215			}
216		};
217		walk(profileDir(), 2);
218		walk(projectDir(slug), 2);
219		return out;
220	}
221	export interface Extractor {
222		/**
223		 * Pass a fresh ctx every call. Capturing ctx across session replacement
224		 * (newSession/fork/switchSession/reload) makes it stale and forkAgent will throw.
225		 *
226		 * Per-turn extraction (CC `extractMemories` parity), fire-and-forget from
227		 * turn_end. `opts.shutdown` is the session-end final flush — it bypasses the
228		 * MIN_NEW_TURNS throttle so a short session's memories aren't lost. The
229		 * pollution skip, lock mutex, and direct-write mutex still apply.
230		 */
231		maybeRun(ctx: ExtensionContext, opts?: { shutdown?: boolean }): Promise<string[]>;
232		drain(timeoutMs?: number): Promise<void>;
233	}
234	const ALLOWED_FORK_TOOLS = ["read", "grep", "find", "ls", "bash", "write", "edit"];
235	
236	// Turn throttle — CC's `tengu_bramble_lintel` analog: run extraction at most
237	// every N new turns. Default 1 = CC's every-turn cadence. Raise via
238	// PI_MEMORY_MIN_NEW_TURNS if the per-turn Opus fork cost bites. The shutdown
239	// flush bypasses this floor.
240	const MIN_NEW_TURNS = (): number => {
241		const v = Number(process.env.PI_MEMORY_MIN_NEW_TURNS);
242		return Number.isFinite(v) && v >= 1 ? Math.floor(v) : 1;
243	};
244	
245	// Per-fork output bound — caps Opus runaway prose on each extraction turn.
246	// Tune via PI_MEMORY_MAX_OUTPUT_TOKENS.
247	const MAX_OUTPUT_TOKENS = (): number => {
248		const v = Number(process.env.PI_MEMORY_MAX_OUTPUT_TOKENS);
249		return Number.isFinite(v) && v > 0 ? Math.floor(v) : 2048;
250	};
251	
252	// Hard turn cap for the extractor fork — CC's `query({ maxTurns: 5 })`. Stops a
253	// runaway extraction from looping (read → read → read …). Tune via
254	// PI_MEMORY_MAX_TURNS; 0/unset keeps the default 5.
255	const MAX_TURNS = (): number => {
256		const v = Number(process.env.PI_MEMORY_MAX_TURNS);
257		return Number.isFinite(v) && v > 0 ? Math.floor(v) : 5;
258	};
259	
260	export function createExtractor(opts: {
261		slug: string;
262		originSessionId: string;
263		/** Total user+assistant turns observed by the parent so far. */
264		getTurnCount: () => number;
265		/** Session-wide flag flipped by the tool_result watcher when a memory write
266		 * lands. Acts as the Path A↔Path B mutex — once Path A writes, Path B stops
267		 * firing for the rest of the session. */
268		memoryWrittenThisSession: () => boolean;
269		model?: string;
270		/** Returns the live pollution-counter for the parent session. */
271		getPollution?: () => PollutionState;
272		/** Called whenever a fork run saves at least one memory file. Fires for both
273		 * the in-flight run and any coalesced trailing run, so transcript.append is
274		 * always reached regardless of coalescing depth.
275		 * Receives the fresh ctx from the triggering event so transcript.append uses
276		 * a live (non-stale) handle even after session replacement. */
277		onSaved?: (ctx: ExtensionContext, paths: string[]) => void;
278	}): Extractor {
279		let cursorTurns = 0;
280		let cur: Promise<string[]> | null = null;
281		let next: { ctx: ExtensionContext; shutdown: boolean } | null = null;
282	
283		async function runOnce(ctx: ExtensionContext, shutdown: boolean): Promise<string[]> {
284			const turnsNow = opts.getTurnCount();
285			// Sub-agent guard: refuse to fork an extractor from inside a child agent.
286			// The fork would run in the same process and re-trigger turn_end, which
287			// would re-enter the extractor and fork again. Belt + braces: the parent
288			// extension's hooks also bail when ctx.source === "child-agent", but
289			// anyone with a raw extractor handle could still call maybeRun() directly.
290			if (isMemorySubAgentCtx(ctx)) {
291				cursorTurns = turnsNow;
292				return [];
293			}
294			// Mutex: once the main agent has written memory this session, Path B is
295			// redundant. Skip and let the cursor stay where it is.
296			if (opts.memoryWrittenThisSession()) {
297				cursorTurns = turnsNow;
298				return [];
299			}
300			const newTurns = turnsNow - cursorTurns;
301			// Turn throttle (CC's tengu_bramble_lintel analog). The shutdown flush
302			// bypasses it so a short session's memories aren't lost.
303			if (!shutdown && newTurns < MIN_NEW_TURNS()) return [];
304			if (typeof ctx.forkAgent !== "function") {
305				console.warn("[pi-memory] forkAgent is not available in this context, skipping extraction");
306				return [];
307			}
308	
309			// ── extraction guards (CC extractMemories parity) ────────────────────
310			// No time/session gate. Pollution skip + lock mutex + the direct-write
311			// mutex (above) are the only guards. Cross-session dedup/consolidation is
312			// dream-memory's job (CC's autoDream), not the extractor's.
313			const scope: Scope = scopeForSlug(opts.slug);
314			const pollution = opts.getPollution?.() ?? newPollutionState();
315			if (isPolluted(pollution)) {
316				cursorTurns = turnsNow;
317				return [];
318			}
319	
320			// ── lock acquisition ────────────────────────────────────────────────
321			let priorMtime: number | null;
322			try {
323				priorMtime = await tryAcquireConsolidationLock(scope);
324			} catch (err) {
325				console.error("[pi-memory] lock acquire failed:", err);
326				return [];
327			}
328			if (priorMtime === null) {
329				if (process.env.PI_MEMORY_DEBUG) {
330					console.error(`[pi-memory.gate] fired=false reason=lock scope=${scope}`);
331				}
332				return [];
333			}
334	
335			const before = snapshot(opts.slug);
336			// The forked agent's recursion-prone cascades (active-recall, dream-enqueue,
337			// nested extractor forks, memory_note, save-prompt inject) are skipped via
338			// `BeforeAgentStartEvent.source === "child-agent"`: pi's agent-tool executor
339			// tags every in-process `ctx.forkAgent` call with that source, and the
340			// memory extensions gate on it in their hooks. No env mutation required —
341			// the old `PI_MEMORY_SUBAGENT=1` block was a race waiting to happen under
342			// parallel forks sharing one Node process.
343			try {
344				const { handle } = await ctx.forkAgent({
345					prompt: buildExtractPrompt({
346						newMessageCount: Math.max(newTurns, 1),
347						existingMemories: [...before.keys()].map((f) => `- ${f}`).join("\n"),
348						slug: opts.slug,
349						originSessionId: opts.originSessionId,
350					}),
351					allowedTools: ALLOWED_FORK_TOOLS,
352					model: opts.model,
353					description: "pi-memory extraction",
354					// L1+L2 cache stability (see docs/cache-strategy.md):
355					//   context:"none"   — skip parent transcript, project context, skills,
356					//                     and agent-append. Resource loader does no work.
357					//   systemPrompt    — byte-stable across every session and cwd,
358					//                     so Anthropic's prompt cache hits cross-session
359					//                     (1h TTL via claude-bridge BRIDGE_CACHE_TTL).
360					//   maxOutputTokens — cap verbose Opus reasoning on a 3-tool job.
361					context: "none",
362					systemPrompt: STABLE_EXTRACTOR_SYSTEM_PROMPT,
363					// CC extractMemories parity: cap the agentic loop at maxTurns (5) so a
364					// runaway extraction can't loop, and bound per-turn Opus output.
365					maxTurns: MAX_TURNS(),
366					maxOutputTokens: MAX_OUTPUT_TOKENS(),
367				});
368				await handle.wait();
369				cursorTurns = turnsNow;
370				const after = snapshot(opts.slug);
371				const changed: string[] = [];
372				for (const [p, t] of after) if (before.get(p) !== t) changed.push(p);
373				// On success: refresh lock mtime BEFORE calling onSaved. If the callback
374				// throws a stale-ctx error (session replaced while the fork ran) we still
375				// record the successful extraction — not rolling back the lock.
376				await touchConsolidationSuccess(scope);
377				if (changed.length > 0) {
378					try {
379						opts.onSaved?.(ctx, changed);
380					} catch (err) {
381						if (err instanceof Error && err.message.includes("ctx is stale")) {
382							// Expected race: session replaced while fork ran.
383							// Extraction succeeded — transcript.append is best-effort.
384						} else {
385							console.error("[pi-memory] onSaved callback failed:", err);
386						}
387					}
388				}
389				return changed;
390			} catch (err) {
391				// Roll back the mutex so the next turn can re-acquire and retry.
392				await rollbackConsolidationLock(scope, priorMtime).catch(() => {});
393				// Stale ctx is an expected race: the session was replaced between when this
394				// run was scheduled and when forkAgent fired. Swallow silently — the
395				// session is gone, there's nothing to extract for.
396				if (err instanceof Error && err.message.includes("ctx is stale")) return [];
397				console.error("[pi-memory] fork failed:", err);
398				return [];
399			}
400		}
401		function maybeRun(ctx: ExtensionContext, opts: { shutdown?: boolean } = {}): Promise<string[]> {
402			const shutdown = opts.shutdown ?? false;
403			if (cur) {
404				// Coalesce trailing run; always use the freshest ctx so when it fires it
405				// runs against the current session, not a stale captured one. A shutdown
406				// flush chasing an in-flight ambient run still flushes.
407				next = { ctx, shutdown: (next?.shutdown ?? false) || shutdown };
408				return cur;
409			}
410			cur = (async (): Promise<string[]> => {
411				try {
412					return await runOnce(ctx, shutdown);
413				} finally {
414					const n = next;
415					next = null;
416					cur = null;
417					if (n) cur = maybeRun(n.ctx, { shutdown: n.shutdown });
418				}
419			})();
420			return cur;
421		}
422		async function drain(timeoutMs = 60_000): Promise<void> {
423			const deadline = Date.now() + timeoutMs;
424			while (cur && Date.now() < deadline) {
425				await Promise.race([cur.catch(() => {}), new Promise<void>((r) => setTimeout(r, Math.max(0, deadline - Date.now())).unref?.())]);
426			}
427		}
428		return { maybeRun, drain };
429	}
430	
431	export type TranscriptEntry = { kind: "memory_saved"; verb: "Saved" | "Improved"; paths: string[] };
432	
433	/**
434	 * Local forkAgent shim: Luke's pi fork supports these fields, while the
435	 * published upstream types may lag behind. Keep the extension typecheckable
436	 * against both without importing fork-only type exports.
437	 */
438	export type ForkAgentOptionsExt = {
439		prompt: string;
440		allowedTools?: string[];
441		model?: string;
442		description?: string;
443		context?: "fork" | "slim" | "none";
444		systemPrompt?: string;
445		maxOutputTokens?: number;
446		maxTurns?: number;
447	};
448	
449	type ForkAgentResultExt = ForkAgentResult;
450	
451	export interface ExtensionContext extends BaseCtx {
452		forkAgent(opts: ForkAgentOptionsExt): Promise<ForkAgentResultExt>;
453		readonly transcript: { append(entry: TranscriptEntry): void };
454	}
