import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { basename, dirname, join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import type { ExtensionContext as BaseCtx, ForkAgentResult } from "@earendil-works/pi-coding-agent";
import {
	isPolluted,
	newPollutionState,
	type PollutionState,
	rollbackConsolidationLock,
	type Scope,
	scopeForSlug,
	touchConsolidationSuccess,
	tryAcquireConsolidationLock,
} from "./gate.js";
export const memoryRoot = (): string => (process.env.PI_MEMORY_DIR?.length ? resolve(process.env.PI_MEMORY_DIR) : join(homedir(), ".pi", "agent", "memory"));

/**
 * Detect a memory sub-agent run from the AgentSession's source field.
 *
 * A sub-agent run is any AgentSession whose `ExtensionContext.source` is
 * `"child-agent"` (in-process delegated runs via the built-in `agent` tool /
 * `ctx.forkAgent`, or out-of-process Pi children spawned with
 * `pi --source child-agent`). When true, the pi-memory extension skips the
 * save-prompt inject, the turn_end extractor fork, and the session_shutdown
 * journal append — preventing fork-of-fork recursion when the extractor's
 * own child fires turn_end inside the same process.
 *
 * Replaces the legacy `PI_MEMORY_SUBAGENT=1` env contract: typed, race-free
 * under parallel fan-out, mirrors dream-memory's reader in the same package.
 */
export function isMemorySubAgentCtx(ctx: unknown): boolean {
	return (ctx as { source?: string } | null | undefined)?.source === "child-agent";
}
export const profileDir = (): string => join(memoryRoot(), "profile");
export const projectDir = (slug: string): string => join(memoryRoot(), "project", slug);
export const journalDir = (): string => (process.env.PI_JOURNAL_DIR?.length ? resolve(process.env.PI_JOURNAL_DIR) : join(homedir(), ".pi", "agent", "journal"));
export function isMemoryPath(p: string | undefined): boolean {
	if (!p) return false;
	const abs = resolve(p);
	const r = memoryRoot();
	return abs === r || abs.startsWith(r + sep);
}

// slug — vendored from dream-memory-harness/src/store.ts; slug-map persistence dropped. TODO: extract into shared @howaboua/pi-slug package.
const SLUG_RE = /^[a-z0-9][a-z0-9._-]*$/;
const norm = (raw: string): string => {
	const s = raw
		.trim()
		.toLowerCase()
		.replace(/[^a-z0-9._-]/g, "-")
		.replace(/^-+|-+$/g, "");
	return s || "unnamed";
};
async function findUp(start: string, name: string): Promise<string | null> {
	let dir = resolve(start);
	for (;;) {
		const c = join(dir, name);
		if (existsSync(c)) return c;
		const p = dirname(dir);
		if (p === dir) return null;
		dir = p;
	}
}
export async function resolveProjectSlug(cwd: string): Promise<string> {
	const abs = resolve(cwd);
	let slug: string | null = null;
	const y = await findUp(abs, ".dream-memory.yml");
	if (y) {
		try {
			const m = /^[ \t]*project_slug[ \t]*:[ \t]*["']?([^"'\n#]+)["']?/m.exec(await readFile(y, "utf8"));
			if (m?.[1]) slug = norm(m[1].trim());
		} catch {}
	}
	if (!slug) {
		const gitDir = await findUp(abs, ".git");
		const cfg = gitDir && join(gitDir, "config");
		if (cfg && existsSync(cfg)) {
			const rs = [...(await readFile(cfg, "utf8")).matchAll(/\[remote "([^"]+)"\][^[]*?url\s*=\s*(\S+)/g)];
			const url = (rs.find((m) => m[1] === "origin") ?? rs[0])?.[2];
			const seg = url
				?.replace(/\.git$/, "")
				.split(/[/:]/)
				.filter(Boolean)
				.pop();
			if (seg) slug = norm(seg);
		}
	}
	if (!slug) slug = norm(basename(abs));
	if (!SLUG_RE.test(slug)) throw new Error(`resolveProjectSlug: invalid slug "${slug}" for ${abs}`);
	return slug;
}

const PROMPTS_DIR = join(fileURLToPath(new URL(".", import.meta.url)), "..", "prompts");
const loadPrompt = (n: string): string => readFileSync(join(PROMPTS_DIR, n), "utf8").trimEnd();
const fill = (tpl: string, vars: Record<string, string>): string => tpl.replace(/\{\{([A-Z_]+)\}\}/g, (_, k) => vars[k] ?? `{{${k}}}`);

/**
 * Stable extractor system prompt.
 *
 * Byte-identical across every session, every cwd, every project. Contains zero
 * per-session substitutions — slug, sessionId, and absolute memory paths live
 * in the per-call user prompt only. Memoised at module load.
 *
 * Used as the `systemPrompt` override for `ctx.forkAgent({ context: "none", systemPrompt })`
 * so the Anthropic prompt cache hits across all extractor invocations on the
 * account (per-day TTL via claude-bridge BRIDGE_CACHE_TTL=1h).
 *
 * Mirrors Claude Code's Task tool pattern: launcher pre-builds the system
 * prompt, child uses it verbatim. See `~/Projects/personal/my-pi/docs/cache-strategy.md`.
 */
const STABLE_EXTRACTOR_SYSTEM_PROMPT: string = loadPrompt("extractor-stable-system.md");
export function buildStableExtractorSystemPrompt(): string {
	return STABLE_EXTRACTOR_SYSTEM_PROMPT;
}

function memVars(slug: string, originSessionId: string): Record<string, string> {
	return { PROJECT_SLUG: slug, ORIGIN_SESSION_ID: originSessionId, MEMORY_ROOT: memoryRoot(), PROFILE_DIR: profileDir(), PROJECT_DIR: projectDir(slug) };
}
export function buildParentMemoryPromptSection(slug: string, originSessionId: string): string {
	const vars = memVars(slug, originSessionId);
	return [
		"# Memory",
		`You have a persistent memory system rooted at \`${vars.MEMORY_ROOT}/\`.`,
		"Use memory when the user asks to recall/remember, or when injected memory is clearly relevant. Treat memories as stale hints: verify file paths, functions, flags, and current repo state before acting.",
		"Do not save secrets, transient task state, derivable repo facts, git history, debugging recipes, or anything already documented in MEMORY.md, AGENTS.md, CLAUDE.md, or skill files.",
		"If the user explicitly asks you to save or forget a memory inline, use `write`/`edit` to update a typed markdown file plus the matching MEMORY.md index. Types: `user`, `feedback`, `project`, `reference`. Filenames must start with the type, e.g. `feedback_no_db_mocks.md`. Include frontmatter: `name`, `description`, `type`, `originSessionId`.",
		`Save cross-project memories under \`${vars.PROFILE_DIR}/\`; save project-specific memories under \`${vars.PROJECT_DIR}/\`. Current project slug: \`${slug}\`. Current pi session id: \`${originSessionId}\`.`,
		"For detailed save rules, load the `pi-memory-save` skill before writing non-trivial memories. Background extraction normally handles memory writes automatically.",
	].join("\n\n");
}
export function buildFullSavePromptSection(slug: string, originSessionId: string): string {
	const parts = [
		`# Memory\n\nYou have a persistent memory system rooted at \`${memoryRoot()}/\`.`,
		loadPrompt("types-individual.md"),
		loadPrompt("what-not-to-save.md"),
		fill(loadPrompt("save-instructions.md"), memVars(slug, originSessionId)),
		loadPrompt("recall-guidance.md"),
	];
	return parts.join("\n\n");
}
export function buildExtractPrompt(o: { newMessageCount: number; existingMemories: string; slug: string; originSessionId: string }): string {
	const block = o.existingMemories.trim()
		? `## Existing memory files\n\n${o.existingMemories.trim()}\n\nCheck this list before writing — update an existing file rather than creating a duplicate.`
		: "";
	return fill(loadPrompt("extract-prompt.md"), { NEW_MESSAGE_COUNT: String(o.newMessageCount), EXISTING_MEMORIES_BLOCK: block, ...memVars(o.slug, o.originSessionId) });
}

export interface JournalState {
	userMsgCount: number;
	assistantMsgCount: number;
	toolCounts: Map<string, number>;
	fileEditCounts: Map<string, number>;
	firstUser: string | undefined;
	lastAssistant: string | undefined;
	memoryWrittenThisSession: boolean;
}
export const newJournalState = (): JournalState => ({
	userMsgCount: 0,
	assistantMsgCount: 0,
	toolCounts: new Map(),
	fileEditCounts: new Map(),
	firstUser: undefined,
	lastAssistant: undefined,
	memoryWrittenThisSession: false,
});
/** ≥2 user msgs OR ≥1 tool call, AND no memory write this session (mutex). */
export function isSubstantive(s: JournalState): boolean {
	if (s.memoryWrittenThisSession) return false;
	if (s.userMsgCount >= 2) return true;
	let t = 0;
	for (const n of s.toolCounts.values()) t += n;
	return t >= 1;
}
const trim1 = (s: string | undefined, max = 200): string => {
	const f = (s ?? "").replace(/\s+/g, " ").trim();
	return f.length > max ? `${f.slice(0, max - 1)}…` : f;
};
export function renderJournalEntry(s: JournalState, i: { sessionId: string; slug: string; now?: Date }): string {
	const ts = (i.now ?? new Date()).toISOString().replace(/\.\d+Z$/, "Z");
	const sortByCount = <T>(m: Map<T, number>) => [...m].sort((a, b) => b[1] - a[1]);
	const tools = sortByCount(s.toolCounts)
		.map(([n, c]) => `${n}×${c}`)
		.join(", ");
	const files = sortByCount(s.fileEditCounts)
		.slice(0, 5)
		.map(([f]) => f);
	const out = [`## ${ts} [sid:${i.sessionId}]`, `- cwd: ${i.slug}`, `- msgs: ${s.userMsgCount} user / ${s.assistantMsgCount} assistant`];
	if (tools) out.push(`- tools: ${tools}`);
	if (files.length) out.push(`- files: ${files.join(", ")}`);
	if (s.firstUser) out.push(`- first_user: "${trim1(s.firstUser)}"`);
	if (s.lastAssistant) out.push(`- last_assistant: "${trim1(s.lastAssistant)}"`);
	return `${out.join("\n")}\n\n`;
}
export function appendJournal(entry: string, now: Date = new Date()): string {
	const d = journalDir();
	if (!existsSync(d)) mkdirSync(d, { recursive: true });
	const file = join(d, `${now.toISOString().slice(0, 10)}.md`);
	appendFileSync(file, entry, "utf8");
	return file;
}

function snapshot(slug: string): Map<string, number> {
	const out = new Map<string, number>();
	const walk = (d: string, left: number): void => {
		if (!existsSync(d)) return;
		for (const e of readdirSync(d)) {
			const f = join(d, e);
			try {
				const st = statSync(f);
				if (st.isDirectory() && left > 0) walk(f, left - 1);
				else if (st.isFile() && e.endsWith(".md")) out.set(f, st.mtimeMs);
			} catch {}
		}
	};
	walk(profileDir(), 2);
	walk(projectDir(slug), 2);
	return out;
}
export interface Extractor {
	/**
	 * Pass a fresh ctx every call. Capturing ctx across session replacement
	 * (newSession/fork/switchSession/reload) makes it stale and forkAgent will throw.
	 *
	 * Per-turn extraction (CC `extractMemories` parity), fire-and-forget from
	 * turn_end. `opts.shutdown` is the session-end final flush — it bypasses the
	 * MIN_NEW_TURNS throttle so a short session's memories aren't lost. The
	 * pollution skip, lock mutex, and direct-write mutex still apply.
	 */
	maybeRun(ctx: ExtensionContext, opts?: { shutdown?: boolean }): Promise<string[]>;
	drain(timeoutMs?: number): Promise<void>;
}
const ALLOWED_FORK_TOOLS = ["read", "grep", "find", "ls", "bash", "write", "edit"];

// Turn throttle — CC's `tengu_bramble_lintel` analog: run extraction at most
// every N new turns. Default 1 = CC's every-turn cadence. Raise via
// PI_MEMORY_MIN_NEW_TURNS if the per-turn Opus fork cost bites. The shutdown
// flush bypasses this floor.
const MIN_NEW_TURNS = (): number => {
	const v = Number(process.env.PI_MEMORY_MIN_NEW_TURNS);
	return Number.isFinite(v) && v >= 1 ? Math.floor(v) : 1;
};

// Per-fork output bound — caps Opus runaway prose on each extraction turn.
// Tune via PI_MEMORY_MAX_OUTPUT_TOKENS.
const MAX_OUTPUT_TOKENS = (): number => {
	const v = Number(process.env.PI_MEMORY_MAX_OUTPUT_TOKENS);
	return Number.isFinite(v) && v > 0 ? Math.floor(v) : 2048;
};

// Hard turn cap for the extractor fork — CC's `query({ maxTurns: 5 })`. Stops a
// runaway extraction from looping (read → read → read …). Tune via
// PI_MEMORY_MAX_TURNS; 0/unset keeps the default 5.
const MAX_TURNS = (): number => {
	const v = Number(process.env.PI_MEMORY_MAX_TURNS);
	return Number.isFinite(v) && v > 0 ? Math.floor(v) : 5;
};

export function createExtractor(opts: {
	slug: string;
	originSessionId: string;
	/** Total user+assistant turns observed by the parent so far. */
	getTurnCount: () => number;
	/** Session-wide flag flipped by the tool_result watcher when a memory write
	 * lands. Acts as the Path A↔Path B mutex — once Path A writes, Path B stops
	 * firing for the rest of the session. */
	memoryWrittenThisSession: () => boolean;
	model?: string;
	/** Returns the live pollution-counter for the parent session. */
	getPollution?: () => PollutionState;
	/** Called whenever a fork run saves at least one memory file. Fires for both
	 * the in-flight run and any coalesced trailing run, so transcript.append is
	 * always reached regardless of coalescing depth.
	 * Receives the fresh ctx from the triggering event so transcript.append uses
	 * a live (non-stale) handle even after session replacement. */
	onSaved?: (ctx: ExtensionContext, paths: string[]) => void;
}): Extractor {
	let cursorTurns = 0;
	let cur: Promise<string[]> | null = null;
	let next: { ctx: ExtensionContext; shutdown: boolean } | null = null;

	async function runOnce(ctx: ExtensionContext, shutdown: boolean): Promise<string[]> {
		const turnsNow = opts.getTurnCount();
		// Sub-agent guard: refuse to fork an extractor from inside a child agent.
		// The fork would run in the same process and re-trigger turn_end, which
		// would re-enter the extractor and fork again. Belt + braces: the parent
		// extension's hooks also bail when ctx.source === "child-agent", but
		// anyone with a raw extractor handle could still call maybeRun() directly.
		if (isMemorySubAgentCtx(ctx)) {
			cursorTurns = turnsNow;
			return [];
		}
		// Mutex: once the main agent has written memory this session, Path B is
		// redundant. Skip and let the cursor stay where it is.
		if (opts.memoryWrittenThisSession()) {
			cursorTurns = turnsNow;
			return [];
		}
		const newTurns = turnsNow - cursorTurns;
		// Turn throttle (CC's tengu_bramble_lintel analog). The shutdown flush
		// bypasses it so a short session's memories aren't lost.
		if (!shutdown && newTurns < MIN_NEW_TURNS()) return [];
		if (typeof ctx.forkAgent !== "function") {
			console.warn("[pi-memory] forkAgent is not available in this context, skipping extraction");
			return [];
		}

		// ── extraction guards (CC extractMemories parity) ────────────────────
		// No time/session gate. Pollution skip + lock mutex + the direct-write
		// mutex (above) are the only guards. Cross-session dedup/consolidation is
		// dream-memory's job (CC's autoDream), not the extractor's.
		const scope: Scope = scopeForSlug(opts.slug);
		const pollution = opts.getPollution?.() ?? newPollutionState();
		if (isPolluted(pollution)) {
			cursorTurns = turnsNow;
			return [];
		}

		// ── lock acquisition ────────────────────────────────────────────────
		let priorMtime: number | null;
		try {
			priorMtime = await tryAcquireConsolidationLock(scope);
		} catch (err) {
			console.error("[pi-memory] lock acquire failed:", err);
			return [];
		}
		if (priorMtime === null) {
			if (process.env.PI_MEMORY_DEBUG) {
				console.error(`[pi-memory.gate] fired=false reason=lock scope=${scope}`);
			}
			return [];
		}

		const before = snapshot(opts.slug);
		// The forked agent's recursion-prone cascades (active-recall, dream-enqueue,
		// nested extractor forks, memory_note, save-prompt inject) are skipped via
		// `BeforeAgentStartEvent.source === "child-agent"`: pi's agent-tool executor
		// tags every in-process `ctx.forkAgent` call with that source, and the
		// memory extensions gate on it in their hooks. No env mutation required —
		// the old `PI_MEMORY_SUBAGENT=1` block was a race waiting to happen under
		// parallel forks sharing one Node process.
		try {
			const { handle } = await ctx.forkAgent({
				prompt: buildExtractPrompt({
					newMessageCount: Math.max(newTurns, 1),
					existingMemories: [...before.keys()].map((f) => `- ${f}`).join("\n"),
					slug: opts.slug,
					originSessionId: opts.originSessionId,
				}),
				allowedTools: ALLOWED_FORK_TOOLS,
				model: opts.model,
				description: "pi-memory extraction",
				// L1+L2 cache stability (see docs/cache-strategy.md):
				//   context:"none"   — skip parent transcript, project context, skills,
				//                     and agent-append. Resource loader does no work.
				//   systemPrompt    — byte-stable across every session and cwd,
				//                     so Anthropic's prompt cache hits cross-session
				//                     (1h TTL via claude-bridge BRIDGE_CACHE_TTL).
				//   maxOutputTokens — cap verbose Opus reasoning on a 3-tool job.
				context: "none",
				systemPrompt: STABLE_EXTRACTOR_SYSTEM_PROMPT,
				// CC extractMemories parity: cap the agentic loop at maxTurns (5) so a
				// runaway extraction can't loop, and bound per-turn Opus output.
				maxTurns: MAX_TURNS(),
				maxOutputTokens: MAX_OUTPUT_TOKENS(),
			});
			await handle.wait();
			cursorTurns = turnsNow;
			const after = snapshot(opts.slug);
			const changed: string[] = [];
			for (const [p, t] of after) if (before.get(p) !== t) changed.push(p);
			// On success: refresh lock mtime BEFORE calling onSaved. If the callback
			// throws a stale-ctx error (session replaced while the fork ran) we still
			// record the successful extraction — not rolling back the lock.
			await touchConsolidationSuccess(scope);
			if (changed.length > 0) {
				try {
					opts.onSaved?.(ctx, changed);
				} catch (err) {
					if (err instanceof Error && err.message.includes("ctx is stale")) {
						// Expected race: session replaced while fork ran.
						// Extraction succeeded — transcript.append is best-effort.
					} else {
						console.error("[pi-memory] onSaved callback failed:", err);
					}
				}
			}
			return changed;
		} catch (err) {
			// Roll back the mutex so the next turn can re-acquire and retry.
			await rollbackConsolidationLock(scope, priorMtime).catch(() => {});
			// Stale ctx is an expected race: the session was replaced between when this
			// run was scheduled and when forkAgent fired. Swallow silently — the
			// session is gone, there's nothing to extract for.
			if (err instanceof Error && err.message.includes("ctx is stale")) return [];
			console.error("[pi-memory] fork failed:", err);
			return [];
		}
	}
	function maybeRun(ctx: ExtensionContext, opts: { shutdown?: boolean } = {}): Promise<string[]> {
		const shutdown = opts.shutdown ?? false;
		if (cur) {
			// Coalesce trailing run; always use the freshest ctx so when it fires it
			// runs against the current session, not a stale captured one. A shutdown
			// flush chasing an in-flight ambient run still flushes.
			next = { ctx, shutdown: (next?.shutdown ?? false) || shutdown };
			return cur;
		}
		cur = (async (): Promise<string[]> => {
			try {
				return await runOnce(ctx, shutdown);
			} finally {
				const n = next;
				next = null;
				cur = null;
				if (n) cur = maybeRun(n.ctx, { shutdown: n.shutdown });
			}
		})();
		return cur;
	}
	async function drain(timeoutMs = 60_000): Promise<void> {
		const deadline = Date.now() + timeoutMs;
		while (cur && Date.now() < deadline) {
			await Promise.race([cur.catch(() => {}), new Promise<void>((r) => setTimeout(r, Math.max(0, deadline - Date.now())).unref?.())]);
		}
	}
	return { maybeRun, drain };
}

export type TranscriptEntry = { kind: "memory_saved"; verb: "Saved" | "Improved"; paths: string[] };

/**
 * Local forkAgent shim: Luke's pi fork supports these fields, while the
 * published upstream types may lag behind. Keep the extension typecheckable
 * against both without importing fork-only type exports.
 */
export type ForkAgentOptionsExt = {
	prompt: string;
	allowedTools?: string[];
	model?: string;
	description?: string;
	context?: "fork" | "slim" | "none";
	systemPrompt?: string;
	maxOutputTokens?: number;
	maxTurns?: number;
};

type ForkAgentResultExt = ForkAgentResult;

export interface ExtensionContext extends BaseCtx {
	forkAgent(opts: ForkAgentOptionsExt): Promise<ForkAgentResultExt>;
	readonly transcript: { append(entry: TranscriptEntry): void };
}

