294	const PROFILE_MEMORY_PATH = `${process.env.HOME ?? "/Users/luke"}/.pi/agent/dream-memory/profile-memory.md`;
295	const PROFILE_BLOCK_OPEN = `<project_instructions path="${PROFILE_MEMORY_PATH}">`;
296	const PC_OPEN_TAG = "<project_context>";
297	
298	// extendBase parses <project_instructions> blocks by non-greedy regex and keys
299	// a path multiset off them; profile text carrying these tokens would corrupt
300	// that parse, so such content is NOT placed in the base — before_agent_start
301	// falls back to the tail (no content loss, just no cross-cwd cache).
302	function isProfileBaseSafe(content: string): boolean {
303		return !content.includes("</project_instructions>") && !content.includes('<project_instructions path="');
304	}
