// ---------------------------------------------------------------------------
// Stable profile memory → cacheable base (systemPrompt:build filter).
//
// profile/** is global + cwd-independent, so it belongs in the cross-cwd
// SHARED base, not the per-cwd dynamic tail. We inject it as the FIRST
// <project_instructions> block inside <project_context>, with a path under
// ~/.pi/agent/, so the cache-base-prompt extension (PI_EXTEND_BASE_PROMPT=1)
// pulls it above SYSTEM_PROMPT_DYNAMIC_BOUNDARY into the shared base. When that
// flag is off the block harmlessly leads the dynamic tail (no regression).
// Volatile per-cwd memory (project/<slug>/MEMORY.md) stays in the
// before_agent_start tail via dispatchSessionStart.
//
// ORDERING: systemPrompt:build filters run BEFORE before_agent_start handlers
// (runner.ts _runBeforeAgentStart), and cache-base-prompt runs at priority 90,
// so profile MUST be injected here (priority 10) to land above the relocated
// boundary. Anything appended in before_agent_start is below it.
//
// CACHE: profile is loaded once per process + memoised → byte-stable across
// turns and cwds. The filter body still executes on child/fork turns (core
// discards the output when the prompt is frozen, agent-session.ts), so it stays
// cheap: memoised read + a string splice.

const PROFILE_MEMORY_PATH = `${process.env.HOME ?? "/Users/luke"}/.pi/agent/dream-memory/profile-memory.md`;
const PROFILE_BLOCK_OPEN = `<project_instructions path="${PROFILE_MEMORY_PATH}">`;
const PC_OPEN_TAG = "<project_context>";

// extendBase parses <project_instructions> blocks by non-greedy regex and keys
// a path multiset off them; profile text carrying these tokens would corrupt
// that parse, so such content is NOT placed in the base — before_agent_start
// falls back to the tail (no content loss, just no cross-cwd cache).
function isProfileBaseSafe(content: string): boolean {
	return !content.includes("</project_instructions>") && !content.includes('<project_instructions path="');
}

type ProfileSnapshot = { block: string; content: string; safe: boolean };
let _profileSnapshot: ProfileSnapshot | null | undefined;

/** Load + memoise the stable profile snapshot. `null` = no profile content. */
async function getProfileSnapshot(): Promise<ProfileSnapshot | null> {
	if (_profileSnapshot !== undefined) return _profileSnapshot;
	try {
		const { content } = await loadProfileContext({
			maxBytes: SESSION_START_MAX_BYTES,
			maxFiles: SESSION_START_MAX_FILES,
		});
		const trimmed = content.trim();
		if (!trimmed) {
			_profileSnapshot = null;
			return null;
		}
		_profileSnapshot = {
			block: `${PROFILE_BLOCK_OPEN}\n${trimmed}\n</project_instructions>`,
			content: trimmed,
			safe: isProfileBaseSafe(trimmed),
		};
	} catch {
		_profileSnapshot = null;
	}
	return _profileSnapshot;
}

// True once the filter has placed profile in the system prompt this build, so
// before_agent_start does not also add it to the volatile tail (no dup).
let profilePlacedInBase = false;

/**
 * Insert the profile block as the first <project_instructions> block inside
 * <project_context>, leading cache-base-prompt's contiguous global run.
 * Returns the input unchanged when profile is already present (idempotent), or
 * `null` when there is no <project_context> to splice into.
 */
export function injectProfileBlock(prompt: string, block: string): string | null {
	if (typeof prompt !== "string") return null;
	if (prompt.includes(PROFILE_BLOCK_OPEN)) return prompt; // idempotent
	const pcOpen = prompt.indexOf(PC_OPEN_TAG);
	if (pcOpen === -1) return null;
	const firstBlock = prompt.indexOf('<project_instructions path="', pcOpen);
	const at = firstBlock !== -1 ? firstBlock : pcOpen + PC_OPEN_TAG.length + 1;
	return `${prompt.slice(0, at)}${block}\n\n${prompt.slice(at)}`;
}

export default function register(pi: ExtensionAPI, opts: ExtensionOptions = {}): void {
	// D4: Init telemetry once per process — fire-and-forget so opik/tiktoken
	// load async and don't block extension registration.
	void getTel().then(m => m.initTelemetry());

	pi.registerMessageRenderer(PASSIVE_RECALL_CUSTOM_TYPE, renderPassiveRecall);
	pi.registerMessageRenderer(ACTIVE_RECALL_CUSTOM_TYPE, renderActiveRecall);

	// Inject the stable global profile snapshot into the cacheable base. Runs
	// before cache-base-prompt (priority 90) so the block lands inside the
	// leading global run it relocates above the dynamic boundary. See the
	// PROFILE_MEMORY_PATH block comment above for the full rationale.
	const hooks = (pi as unknown as {
		hooks?: {
			addFilter?: <T>(
				name: string,
				id: string,
				fn: (value: T) => T | Promise<T>,
				opts?: { priority?: number },
			) => void;
		};
	}).hooks;
	hooks?.addFilter?.<string>(
		"systemPrompt:build",
		"pi-dream-memory.profile-base",
		async (systemPrompt: string) => {
			profilePlacedInBase = false;
			if (isDreamMemoryDisabled()) return systemPrompt;
			const snap = await getProfileSnapshot();
			if (!snap || !snap.safe) return systemPrompt;
			const next = injectProfileBlock(systemPrompt, snap.block);
			if (next === null) return systemPrompt;
			profilePlacedInBase = next.includes(PROFILE_BLOCK_OPEN);
			return next;
		},
		{ priority: 10 },
	);

	// /memory — show status or toggle the in-session display of memory components.
	// With no args: prints current config state.
	// With "on" / "off": sets show_ui and updates the footer indicator.
	pi.registerCommand("memory", {
		description: "Show active-memory status, or toggle TUI display: /memory [on|off]",
		handler: async (args, ctx) => {
			if (isDreamMemoryDisabled()) {
				ctx.ui.setStatus("dream-memory", ctx.ui.theme.fg("dim", "🧠 off"));
				ctx.ui.notify("dream + memory disabled globally (~/.dream-memory/disabled)");

