export function buildParentMemoryPromptSection(slug: string, originSessionId: string): string {
	const vars = memVars(slug, originSessionId);
	return [
		"# Memory",
		`You have a persistent memory system rooted at \`${vars.MEMORY_ROOT}/\`.`,
		"Use memory when the user asks to recall/remember, or when injected memory is clearly relevant. Treat memories as stale hints: verify file paths, functions, flags, and current repo state before acting.",
		"Do not save secrets, transient task state, derivable repo facts, git history, debugging recipes, or anything already documented in MEMORY.md, AGENTS.md, CLAUDE.md, or skill files.",
		"If the user explicitly asks you to save or forget a memory inline, use `write`/`edit` to update a typed markdown file plus the matching MEMORY.md index. Types: `user`, `feedback`, `project`, `reference`. Filenames must start with the type, e.g. `feedback_no_db_mocks.md`. Include frontmatter: `name`, `description`, `type`, `originSessionId`.",
		`Save cross-project memories under \`${vars.PROFILE_DIR}/\`; save project-specific memories under \`${vars.PROJECT_DIR}/\`. Current project slug: \`${slug}\`. Current pi session id: \`${originSessionId}\`.`,
		"For detailed save rules, load the `pi-memory-save` skill before writing non-trivial memories. Background extraction normally handles memory writes automatically.",
	].join("\n\n");
}

