export async function dispatchSessionStart(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	let _bytesReturned = 0;
	let _filesReturned = 0;
	try {
		const started = Date.now();
		const { content, files } = await withTimeout(
			(async () => {
				// CACHE CRITICAL: this dispatcher returns only the VOLATILE,
				// per-cwd persistent memory — project/<slug>/MEMORY.md. The
				// stable, global profile/** snapshot is injected separately via
				// the extension's systemPrompt:build filter so it joins the
				// cross-cwd cacheable base instead of the per-cwd dynamic tail.
				// Never inject inbox/raw capture here: it carries event ids and
				// timestamps that change between sessions.
				const project = await loadProjectContext(slug, {
					maxBytes: SESSION_START_MAX_BYTES,
					maxFiles: SESSION_START_MAX_FILES,
				});
				return {
					content: project.content,
					files: [...project.files],
				};
			})(),
			SESSION_START_INJECTION_MS,
			"SessionStart injection",
		);
		_bytesReturned = Buffer.byteLength(content, "utf8");
		_filesReturned = files.length;
		void appendEvent({
			sessionId: hook.sessionId,
			client: hook.client,
			cwd: hook.cwd,
			projectSlug: slug,
			eventType: "RecallInjected",
			payload: {
				where: "SessionStart",
				bytes: _bytesReturned,
				latency_ms: Date.now() - started,
				files: files.length,
				qmd: { state: "skipped", hits: 0, permalinks: [] },
			},
		});
		void getHCTel().then(({ withSpan }) => withSpan("dispatch.sessionStart", {
			bytes_returned: _bytesReturned,
			files_returned: _filesReturned,
		}, async () => {}));
		return { stdout: content, timedOut: false };
	} catch (err) {
		if (err instanceof TimeoutError) {
			void appendEvent({
				sessionId: hook.sessionId,
				client: hook.client,
				cwd: hook.cwd,
				projectSlug: slug,
				eventType: "MemoryInjectionTimeout",
				payload: { where: "SessionStart", budget_ms: SESSION_START_INJECTION_MS },
			});
			return { stdout: "", timedOut: true };
		}
		throw err;
	}
}

