				sessionId: hook.sessionId,
				client: hook.client,
				cwd: hook.cwd,
				projectSlug: slug,
				eventType: "MemoryInjectionTimeout",
				payload: { where: "SessionStart", budget_ms: SESSION_START_INJECTION_MS },
			});
			return { stdout: "", timedOut: true };
		}
		throw err;
	}
}

