function shouldCaptureDump(payload, params, flagText) {
  const trimmed = flagText.trim();
  if (!trimmed) return true;

  let filter = {};
  try {
    filter = JSON.parse(trimmed);
  } catch {
    filter = { marker: trimmed };
  }

  if (filter.marker && !payload.includes(String(filter.marker))) {
    return false;
  }
  if (filter.model && !String(params.model || "").includes(String(filter.model))) {
    return false;
  }
  if (filter.requireTools && (!Array.isArray(params.tools) || params.tools.length === 0)) {
    return false;
  }
  return true;
}

function captureBridgeDump(payload, params) {
  try {
    if (!fs.existsSync(DUMP_FLAG_PATH)) return;
    const flagText = fs.readFileSync(DUMP_FLAG_PATH, "utf8");
    if (!shouldCaptureDump(payload, params, flagText)) return;

    fs.writeFileSync(DUMP_OUTPUT_PATH, payload);
    fs.unlinkSync(DUMP_FLAG_PATH);
    console.log(`[DUMP] wrote ${DUMP_OUTPUT_PATH} (${payload.length} bytes)`);
  } catch (e) {
    console.log("[DUMP] error:", e.message);
  }
}

/**
 * Proxy a request to the Anthropic API using raw HTTP.
 * For streaming: pipes SSE bytes directly (no parsing).

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdir, mkdtemp, readFile, rm, writeFile, chmod } from "node:fs/promises";
import { existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
	dispatch,
	dispatchSessionStart,
	dispatchToolEvent,
	dispatchUserPromptSubmit,
	normalise,
	SESSION_START_INJECTION_MS,
	TimeoutError,
	TOTAL_WALL_BUDGET_MS,
	withTimeout,
} from "../src/harness-cli.ts";
import { appendInboxNote, eventsDir, eventsRoot, memoryDir, __resetQmdUnhealthyLog__ } from "../src/store.ts";
import { __resetQmdHealth__ } from "../src/qmd-health.ts";

let scratch: string;

beforeEach(async () => {
	scratch = await mkdtemp(join(tmpdir(), "dream-cli-"));
	process.env.DREAM_EVENTS_HOME = join(scratch, "events-root");
	process.env.DREAM_WIKI_HOME = join(scratch, "wiki-root");
	await mkdir(join(memoryDir(), "profile"), { recursive: true });
	await mkdir(join(memoryDir(), "project", "demo"), { recursive: true });
	__resetQmdHealth__();
	__resetQmdUnhealthyLog__();
});

afterEach(async () => {
	delete process.env.DREAM_EVENTS_HOME;
	delete process.env.DREAM_WIKI_HOME;
	delete process.env.DREAM_BM_CMD;
	delete process.env.DREAM_QMD_HTTP_PORT;
	delete process.env.RECALL_QMD_MODE;
	await rm(scratch, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------

describe("normalise — per-harness payload shapes collapse to one", () => {
	it("claude payload (snake_case, hook_event_name)", () => {
		const h = normalise("claude", {
			session_id: "abc",
			cwd: "/tmp/repo",
			hook_event_name: "PreToolUse",
			tool_name: "Bash",
			tool_input: { command: "ls" },
			transcript_path: "/tmp/x.jsonl",
		});
		expect(h).toMatchObject({
			client: "claude",
			sessionId: "abc",
			cwd: "/tmp/repo",
			eventType: "PreToolUse",
		});
		expect(h.payload).toEqual({ tool_name: "Bash", tool_input: { command: "ls" } });
	});

	it("codex payload (eventType camelCase, workspaceDir)", () => {
		const h = normalise("codex", {
			sessionId: "cdx-1",
			workspaceDir: "/tmp/repo",
			eventType: "user_prompt_submit",
			prompt: "what changed?",
		});
		expect(h.client).toBe("codex");
		expect(h.eventType).toBe("UserPromptSubmit");
		expect(h.cwd).toBe("/tmp/repo");
		expect(h.payload).toEqual({ prompt: "what changed?" });
	});

	it("pi payload (already-normalised event field)", () => {
		const h = normalise("pi", {
			sessionId: "pi-1",
			cwd: "/tmp/repo",
			event: "Stop",
			reason: "user",
		});
		expect(h.client).toBe("pi");
		expect(h.eventType).toBe("Stop");
		expect(h.payload).toEqual({ reason: "user" });
	});

	it("rejects payloads with no event-type field", () => {
		expect(() => normalise("claude", { session_id: "x", cwd: "/tmp" })).toThrow(/missing event type/);
	});
});

// ---------------------------------------------------------------------------

describe("dispatchSessionStart — deterministic project memory (no timeout race)", () => {
	it("returns only the VOLATILE project MEMORY.md index — profile rides the cacheable base", async () => {
		// Indexes are auto-injected. Profile is NOT in this stdout anymore: the
		// stable global profile snapshot is injected separately via the
		// extension's systemPrompt:build filter so it joins the cross-cwd base.
		await writeFile(join(memoryDir(), "profile", "MEMORY.md"), "# Profile index\n- [p1](p1.md) — bit\n");
		await writeFile(join(memoryDir(), "project", "demo", "MEMORY.md"), "# Demo index\n- [arch](arch.md) — overview\n");
		// Topic files exist but are NOT auto-loaded — progressive disclosure.
		await writeFile(join(memoryDir(), "profile", "p1.md"), "# Profile topic bit\n");
		await writeFile(join(memoryDir(), "project", "demo", "arch.md"), "# Demo arch topic\n");
		const r = await dispatchSessionStart({
			client: "claude",
			sessionId: "s1",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});
		expect(r.timedOut).toBe(false);
		expect(r.stdout).toContain("# Demo index");
		expect(r.stdout).not.toContain("# Profile index"); // moved to the base filter
		expect(r.stdout).not.toContain("# Profile topic bit");
		expect(r.stdout).not.toContain("# Demo arch topic");
		expect(Buffer.byteLength(r.stdout, "utf8")).toBeLessThanOrEqual(24 * 1024);
	});

	it("strips volatile frontmatter from SessionStart persistent memory", async () => {
		await writeFile(
			join(memoryDir(), "profile", "MEMORY.md"),
			[
				"---",
				"source_event_ids:",
				'  - "01HVOLATILE"',
				'last_dreamed_at: "2026-05-28T00:00:00.000Z"',
				"---",
				"# Profile index",
				"- Stable global memory.",
			].join("\n"),
		);
		await writeFile(
			join(memoryDir(), "project", "demo", "MEMORY.md"),
			[
				"---",
				'last_dreamed_at: "2026-05-29T00:00:00.000Z"',
				"---",
				"# Demo index",
				"- Stable project memory.",
			].join("\n"),
		);

		const first = await dispatchSessionStart({
			client: "pi",
			sessionId: "s-stable-1",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});
		const second = await dispatchSessionStart({
			client: "pi",
			sessionId: "s-stable-2",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});

		expect(first.stdout).toContain("# Demo index");
		expect(first.stdout).not.toContain("# Profile index"); // profile is base-injected now
		expect(first.stdout).not.toContain("source_event_ids");
		expect(first.stdout).not.toContain("last_dreamed_at");
		expect(first.stdout).not.toContain("---");
		expect(second.stdout).toBe(first.stdout);
	});

	it("does not inject inbox/raw capture into SessionStart persistent memory", async () => {
		await writeFile(join(memoryDir(), "project", "demo", "MEMORY.md"), "# Demo index\n- Stable project memory.\n");
		await appendInboxNote({
			event_id: "01HZZZ0000000000000000009Q",
			session_id: "sess-dynamic",
			slug: "demo",
			text: "raw dynamic note from a prior turn",
			ts: "2026-05-28T00:00:00.000Z",
		});

		const r = await dispatchSessionStart({
			client: "pi",
			sessionId: "s-no-inbox",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});

		expect(r.stdout).toContain("# Demo index");
		expect(r.stdout).not.toContain("inbox/notes.md");
		expect(r.stdout).not.toContain("raw dynamic note from a prior turn");
	});

	it("no timeout race: project MEMORY.md is always returned in full, never starved to empty", async () => {
		// REGRESSION (cross-session prompt cache): dispatchSessionStart used to
		// wrap the project read in withTimeout(150ms) and return "" on a slow
		// read. That made the first-turn <persistent-memory> bytes
		// nondeterministic — a fast session got the full file, a cold one got
		// empty — bursting the cross-session cache for the cwd. The read is now a
		// plain local readFile (no race), so even a large unrelated corpus can
		// never starve it: every session for a cwd gets byte-identical content.
		await writeFile(
			join(memoryDir(), "project", "demo", "MEMORY.md"),
			"# Demo index\n- Stable project memory line.\n",
		);
		// A big sibling corpus the old 150ms fs walk could have raced against.
		for (let i = 0; i < 200; i++) {
			await writeFile(join(memoryDir(), "profile", `note-${i}.md`), "x".repeat(1024));
		}
		const runs = await Promise.all(
			["a", "b", "c", "d", "e"].map((sid) =>
				dispatchSessionStart({
					client: "pi",
					sessionId: `s-race-${sid}`,
					cwd: join(scratch, "demo"),
					eventType: "SessionStart",
					payload: {},
				}),
			),
		);
		for (const r of runs) {
			expect(r.timedOut).toBe(false); // no timeout branch exists anymore
			expect(r.stdout).toContain("Stable project memory line."); // full content, never ""
			expect(Buffer.byteLength(r.stdout, "utf8")).toBeLessThanOrEqual(24 * 1024);
		}
		// Byte-identical across every session for this cwd → warm cross-session cache.
		const [first, ...rest] = runs.map((r) => r.stdout);
		for (const s of rest) expect(s).toBe(first);
	});
});

// ---------------------------------------------------------------------------

describe("dispatchUserPromptSubmit — search-shaped injection", () => {
	it("formats top-N hits within the 10kB cap when bm returns JSON", async () => {
		const fake = join(scratch, "bm-ok.sh");
		await writeFile(
			fake,
			'#!/bin/sh\ncat <<EOF\n{"results":[{"title":"hit","permalink":"profile/style","matched_chunk":"prefer dashes"}]}\nEOF\n',
		);
		await chmod(fake, 0o755);
		process.env.DREAM_BM_CMD = fake;
		process.env.RECALL_QMD_MODE = "search";
		process.env.DREAM_QMD_HTTP_PORT = "0";
		const r = await dispatchUserPromptSubmit({
			client: "claude",
			sessionId: "s3",
			cwd: join(scratch, "demo"),
			eventType: "UserPromptSubmit",
			payload: { prompt: "what's my style?" },
		});
		expect(r.timedOut).toBe(false);
		expect(r.stdout).toContain("profile/style");
		expect(r.stdout).toContain("prefer dashes");
	});

	it("on bm timeout: empty stdout + logs MemoryInjectionTimeout event", async () => {
		const fake = join(scratch, "bm-slow.sh");
		await writeFile(fake, "#!/bin/sh\nsleep 5\n");
		await chmod(fake, 0o755);
		process.env.DREAM_BM_CMD = fake;
		process.env.RECALL_QMD_MODE = "search";
		process.env.DREAM_QMD_HTTP_PORT = "0";
		// Tighten total budget by pretending the search budget is short via
		// dispatch's outer 200ms cap — UserPromptSubmit's search budget is
		// 1500ms inside, but the outer wall budget is 200ms.
		const r = await dispatch({
			client: "claude",
			sessionId: "s4",
			cwd: join(scratch, "demo"),
			eventType: "UserPromptSubmit",
			payload: { prompt: "anything" },
		});
		expect(r.timedOut).toBe(true);
		expect(r.stdout).toBe("");
		// Allow the fire-and-forget appendEvent to flush.
		await new Promise((res) => setTimeout(res, 250));
		const file = join(eventsDir(), "s4.jsonl");
		expect(existsSync(file)).toBe(true);
		const text = await readFile(file, "utf8");
		expect(text).toContain("MemoryInjectionTimeout");
	});

	it("empty prompt → empty stdout, no search call", async () => {
		// No bmCmd set; would fail loudly if invoked.
		process.env.DREAM_BM_CMD = "/nonexistent/bm";
		process.env.RECALL_QMD_MODE = "search";
		process.env.DREAM_QMD_HTTP_PORT = "0";
		const r = await dispatchUserPromptSubmit({
			client: "claude",
			sessionId: "s5",
			cwd: join(scratch, "demo"),
			eventType: "UserPromptSubmit",
			payload: { prompt: "   " },
		});
		expect(r.stdout).toBe("");
		expect(r.timedOut).toBe(false);
	});

	// P3-ISSUE-1: dispatchUserPromptSubmit must persist the prompt itself,
	// not just run recall. Pre-fix, real Pi sessions captured zero user
	// prompts — dream consolidation was blind to user intent.
	it("persists a UserPromptSubmit event with the raw prompt", async () => {
		const fake = join(scratch, "bm-empty.sh");
		await writeFile(fake, '#!/bin/sh\necho "{\\"results\\":[]}"\n');
		await chmod(fake, 0o755);
		process.env.DREAM_BM_CMD = fake;
		process.env.RECALL_QMD_MODE = "search";
		process.env.DREAM_QMD_HTTP_PORT = "0";

		await dispatchUserPromptSubmit({
			client: "pi",
			sessionId: "ups-log",
			cwd: join(scratch, "demo"),
			eventType: "UserPromptSubmit",
			payload: { prompt: "verify the prompt is logged", first_turn: true },
		});

		// fire-and-forget; allow flush
		await new Promise((res) => setTimeout(res, 100));
		const file = join(eventsDir(), "ups-log.jsonl");
		expect(existsSync(file)).toBe(true);
		const lines = (await readFile(file, "utf8")).trim().split("\n").map((l) => JSON.parse(l));
		const ups = lines.find((e: { event_type: string }) => e.event_type === "UserPromptSubmit");
		expect(ups).toBeDefined();
		expect(ups.payload.prompt).toBe("verify the prompt is logged");
		expect(ups.payload.first_turn).toBe(true);
	});
});

// ---------------------------------------------------------------------------

describe("dispatchToolEvent — Pre/PostToolUse just appendEvent", () => {
	it("writes one event line per call", async () => {
		await dispatchToolEvent({
			client: "claude",
			sessionId: "s6",
			cwd: join(scratch, "demo"),
			eventType: "PreToolUse",
			payload: { tool_name: "Bash", tool_input: { command: "echo hi" } },
		});
		await dispatchToolEvent({
			client: "claude",
			sessionId: "s6",
			cwd: join(scratch, "demo"),
			eventType: "PostToolUse",
			payload: { tool_name: "Bash", tool_response: "hi\n" },
		});
		const file = join(eventsDir(), "s6.jsonl");
		const lines = (await readFile(file, "utf8")).trim().split("\n");
		expect(lines).toHaveLength(2);
		expect(lines[0]).toContain('"event_type":"PreToolUse"');
		expect(lines[1]).toContain('"event_type":"PostToolUse"');
	});
});

// ---------------------------------------------------------------------------

describe("dispatch — total wall budget", () => {
	it("enforces TOTAL_WALL_BUDGET_MS via withTimeout", async () => {
		const fake = join(scratch, "bm-slow2.sh");
		await writeFile(fake, "#!/bin/sh\nsleep 2\n");
		await chmod(fake, 0o755);
		process.env.DREAM_BM_CMD = fake;
		process.env.RECALL_QMD_MODE = "search";
		process.env.DREAM_QMD_HTTP_PORT = "0";
		const t0 = Date.now();
		const r = await dispatch({
			client: "claude",
			sessionId: "s7",
			cwd: join(scratch, "demo"),
			eventType: "UserPromptSubmit",
			payload: { prompt: "hi" },
		});
		const dt = Date.now() - t0;
		expect(r.timedOut).toBe(true);
		expect(dt).toBeLessThan(TOTAL_WALL_BUDGET_MS + 100);
		expect(SESSION_START_INJECTION_MS).toBeLessThan(TOTAL_WALL_BUDGET_MS);
	});
});

// ---------------------------------------------------------------------------

describe("dispatchStop — cadence enqueue", () => {
	it("does NOT enqueue dream when session has zero new events since watermark", async () => {
		// s8 has no prior events and no inbox bytes, so Stop should not write dream-pending.
		// (The session file doesn't exist yet; eventsSinceFor returns 0.)
		await dispatch({
			client: "claude",
			sessionId: "s8-no-events",
			cwd: join(scratch, "demo"),
			eventType: "Stop",
			payload: {},
		});
		expect(existsSync(join(eventsRoot(), "dream-pending"))).toBe(false);
	});

	it("DOES enqueue dream when session has >=1 new event since watermark", async () => {
		// Pre-seed 1 event for s9b; the Stop event tips it to count>=1 since no watermark.
		await dispatchToolEvent({
			client: "claude",
			sessionId: "s9b",
			cwd: join(scratch, "demo"),
			eventType: "PreToolUse",
			payload: { tool_name: "Bash", i: 0 },
		});
		await dispatch({
			client: "claude",
			sessionId: "s9b",
			cwd: join(scratch, "demo"),
			eventType: "Stop",
			payload: {},
		});
		const marker = join(eventsRoot(), "dream-pending");
		expect(existsSync(marker)).toBe(true);
