describe("prompt injection composition", () => {
	test("parent section keeps compact write guidance without the full save manual", () => {
		const out = buildParentMemoryPromptSection("my-slug");
		expect(out).toContain("# Memory");
		expect(out).toContain("persistent memory system rooted");
		expect(out).toContain("Types: `user`, `feedback`, `project`, `reference`");
		expect(out).toContain("feedback_no_db_mocks.md");
		expect(out).toContain("my-slug");
		expect(out).toContain("pi-memory-save");
		expect(out).not.toContain("## Types of memory");
		expect(out).not.toContain("<name>user</name>");
		expect(out).not.toContain("## How to save memories");
	});

	// CACHE REGRESSION: this block is appended to the system prompt every session,
	// so it must carry no per-session volatile data. The pre-fix
	// `Current pi session id: <ulid>` line made the cached prefix unique per
	// session and burst the cross-session prompt cache for every same-cwd
	// session. Guard: same slug → byte-identical output, no session-id token, no
	// volatile frontmatter field, no leaked ULID/UUID.
	test("parent section is byte-stable per cwd and carries no session id", () => {
		const a = buildParentMemoryPromptSection("my-slug");
		const b = buildParentMemoryPromptSection("my-slug");
		expect(a).toBe(b); // deterministic for a fixed cwd slug
		expect(a).not.toMatch(/session id/i);
		expect(a).not.toContain("originSessionId");
		expect(a).not.toMatch(/\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b/); // UUID
		expect(a).not.toMatch(/\b[0-9A-HJKMNP-TV-Z]{26}\b/); // ULID
		// Different cwds differ only by their slug-derived paths (CC parity:
		// project CLAUDE.md differs per project), never by a volatile value.
		expect(buildParentMemoryPromptSection("other-slug")).toContain("other-slug");
	});

	test("full save section remains available for extractor/lazy docs", () => {
		const out = buildFullSavePromptSection("my-slug", "sid-xyz");
		expect(out).toContain("## Types of memory");
		expect(out).toContain("<name>user</name>");
		expect(out).toContain("<name>feedback</name>");
		expect(out).toContain("<name>project</name>");
		expect(out).toContain("<name>reference</name>");
		expect(out).toContain("## What NOT to save in memory");
		expect(out).toContain("MEMORY.md, AGENTS.md, CLAUDE.md, or skill files");
		expect(out).toContain("my-slug");
		expect(out).toContain("sid-xyz");
		expect(out).toContain("## How to save memories");
	});
});

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { newPollutionState, recordToolForPollution } from "./src/gate.js";
import {
	appendJournal,
	buildParentMemoryPromptSection,
	createExtractor,
	type ExtensionContext,
	type Extractor,
	isMemoryPath,
	isMemorySubAgentCtx,
	isSubstantive,
	newJournalState,
	renderJournalEntry,
	resolveProjectSlug,
} from "./src/util.js";

const INJECT_MARKER = "<!-- pi-memory:v2 -->";
export default function piMemoryExtension(pi: ExtensionAPI): void {
	let slug = "unnamed";
	let originSessionId = "";
	let injectedSection = "";
	const journal = newJournalState();
	// Turn counter for Path B cursor. We deliberately do NOT retain the full
	// AgentMessage[] history — pi already keeps it, and storing it here grew the
	// process to OOM on long sessions with large tool-result payloads.
	let turnCount = 0;
	let extractor: Extractor | undefined;
	const writesThisTurn = new Map<string, "write" | "edit">();
	// v3: pollution counter — transient-context tools (web_search, mcp_*) flagged here.
	const pollution = newPollutionState();

	pi.on("session_start", async (_e, ctx) => {
		// Sub-agent guard: skip slug resolution and save-prompt construction.
		// `ctx.source === "child-agent"` is set by pi for in-process delegated
		// runs and out-of-process `pi --source child-agent` spawns — nothing in
		// this extension should fire on their lifecycle.
		if (isMemorySubAgentCtx(ctx)) return;
		const sessionCwd = ctx.cwd;
		const sessionId = ctx.sessionManager.getSessionId();
		try {
			slug = await resolveProjectSlug(sessionCwd);
		} catch (err) {
			console.error("[pi-memory] slug resolution failed:", err);
		}
		originSessionId = sessionId;
		injectedSection = `${INJECT_MARKER}\n${buildParentMemoryPromptSection(slug)}`;
	});

	pi.on("before_agent_start", (event, ctx) => {
		// Per-turn check: prefer event.source (handles extension steers in an
		// otherwise-interactive session) and fall back to session-level
		// ctx.source (for forward-compat / non-input triggered turns). Cast
		// through unknown so this still type-checks against published pi
		// versions that don't yet expose source on BeforeAgentStartEvent.
		const evSrc = (event as unknown as { source?: string }).source;
		if (evSrc === "child-agent" || evSrc === "extension" || isMemorySubAgentCtx(ctx)) return;
		if (!injectedSection || event.systemPrompt.includes(INJECT_MARKER)) return;
		return { systemPrompt: `${event.systemPrompt}\n\n${injectedSection}` };
	});

	pi.on("input", (event, ctx) => {
		// Cast through unknown so this still type-checks against published pi
		// versions whose InputSource union doesn't yet include "child-agent".
		const evSrc = event.source as unknown as string;
		if (evSrc === "child-agent" || evSrc === "extension" || isMemorySubAgentCtx(ctx)) return { action: "continue" };
		if (event.source === "interactive" || event.source === "rpc") {
			journal.userMsgCount++;
			turnCount++;
			if (!journal.firstUser) journal.firstUser = event.text;
		}
		return { action: "continue" };
	});

	pi.on("turn_start", (_e, ctx) => {
		if (isMemorySubAgentCtx(ctx)) return;
		writesThisTurn.clear();
	});

	pi.on("tool_call", (event, ctx) => {
		if (isMemorySubAgentCtx(ctx)) return;
		journal.toolCounts.set(event.toolName, (journal.toolCounts.get(event.toolName) ?? 0) + 1);
		// v3: pollution tracking — web/MCP tools taint the session.
		recordToolForPollution(pollution, event.toolName);
	});

	pi.on("tool_result", (event, ctx) => {
		if (isMemorySubAgentCtx(ctx)) return;
		if (event.isError) return;
		if (event.toolName !== "write" && event.toolName !== "edit") return;
		const input = event.input as Record<string, unknown>;
		const fp = input.file_path ?? input.path;
		if (typeof fp !== "string") return;
		journal.fileEditCounts.set(fp, (journal.fileEditCounts.get(fp) ?? 0) + 1);
		if (isMemoryPath(fp)) {
			writesThisTurn.set(fp, event.toolName as "write" | "edit");
			journal.memoryWrittenThisSession = true;
		}
	});

	pi.on("turn_end", async (event, baseCtx) => {
		// Sub-agent guard: never fork an extractor from inside a memory sub-agent.
		// The fork would re-enter the same process and fire turn_end again. The
		// extractor's own runOnce() also bails on the same source check
		// (belt + braces).
		if (isMemorySubAgentCtx(baseCtx)) return;
		const ctx = baseCtx as ExtensionContext;
		journal.assistantMsgCount++;
		turnCount++;
		const c = (event.message as { content?: unknown }).content;
		if (event.message.role === "assistant" && Array.isArray(c)) {
			const t = c.find((b) => b && typeof b === "object" && (b as { type?: string }).type === "text") as { text?: unknown } | undefined;
			if (typeof t?.text === "string") journal.lastAssistant = t.text;
		}

		// Path A mutex: main agent wrote memory → transcript + skip fork.
		if (writesThisTurn.size > 0) {
			const paths = [...writesThisTurn.keys()];
			const verb = [...writesThisTurn.values()].every((v) => v === "edit") ? "Improved" : "Saved";
			ctx.transcript.append({ kind: "memory_saved", verb, paths });
			writesThisTurn.clear();
			return;
		}

		if (!extractor) {
			extractor = createExtractor({
				slug,
				originSessionId,
				getTurnCount: () => turnCount,
				memoryWrittenThisSession: () => journal.memoryWrittenThisSession,
				getPollution: () => pollution,
				// onSaved owns transcript + mutex for both the in-flight run and any
				// coalesced trailing run, preventing the duplicate "Saved N memories" notification.
				// Receives fresh ctx — do NOT close over the outer ctx, it goes stale
				// after session newSession/fork/switchSession/reload and transcript.append throws.
				onSaved: (freshCtx, paths) => {
					freshCtx.transcript.append({ kind: "memory_saved", verb: "Saved", paths });
					journal.memoryWrittenThisSession = true;
				},
			});
		}
		// CC extractMemories parity: per-turn, fire-and-forget at the end of each
		// completed query loop. The turn throttle (MIN_NEW_TURNS), pollution skip,
		// direct-write mutex, and lock all live in the extractor. Pass the fresh ctx
		// from this event — the extractor must not capture ctx itself; coalesced
		// trailing runs use the latest ctx passed in.
		void extractor.maybeRun(ctx).catch((err) => console.error("[pi-memory] background extraction failed:", err));
	});

	pi.on("session_shutdown", async (event, baseCtx) => {
		if (isMemorySubAgentCtx(baseCtx)) return;
		const ctx = baseCtx as ExtensionContext;
		const sessionId = ctx.sessionManager.getSessionId();
		const isReload = (event as { reason?: string }).reason === "reload";

		// Drain any per-turn extraction still in flight from turn_end.
		try {
			if (extractor) await extractor.drain(60_000);
		} catch (err) {
			console.error("[pi-memory] drain error:", err);
		}

		if (isReload) return;
		if (!isSubstantive(journal)) return;

		// v3.1: "sleep consolidation" — fire one final extraction with the
		// time/throttle/session gates bypassed. Pollution + lock still apply.
		// Skip if the session already wrote memory (Path A mutex) or if the user
		// opted out via PI_MEMORY_SHUTDOWN_TRIGGER=0.
		const shutdownEnabled = process.env.PI_MEMORY_SHUTDOWN_TRIGGER !== "0";
		if (shutdownEnabled && extractor && !journal.memoryWrittenThisSession) {
			try {
				await extractor.maybeRun(ctx, { shutdown: true });
			} catch (err) {
				console.error("[pi-memory] shutdown extraction failed:", err);
			}
		}

		try {
			appendJournal(renderJournalEntry(journal, { sessionId, slug }));
		} catch (err) {
			console.error("[pi-memory] journal append failed:", err);
		}
	});
}

