import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";

const sha = (s) => createHash("sha256").update(s).digest("hex").slice(0, 8);
const KB = (b) => (b / 1024).toFixed(1) + "KB";
// crude token estimate: prose ~3.7 ch/tok, JSON/schema denser ~3.1; blend 3.4
const tok = (b) => Math.round(b / 3.4);

const p = JSON.parse(readFileSync(process.argv[2] || "/tmp/bridge-dump.json", "utf8"));

console.log("model:", p.model);
console.log("top-level keys:", Object.keys(p).join(", "));

// ---- system ----
let sysBytes = 0, sysShape = "none";
if (typeof p.system === "string") { sysBytes = Buffer.byteLength(p.system); sysShape = "string"; }
else if (Array.isArray(p.system)) {
  sysShape = `array[${p.system.length}]`;
  p.system.forEach((b, i) => {
    const t = typeof b.text === "string" ? b.text : JSON.stringify(b);
    const bytes = Buffer.byteLength(t);
    sysBytes += bytes;
    console.log(`  system[${i}] ${KB(bytes)} ~${tok(bytes)}tok cc=${b.cache_control ? JSON.stringify(b.cache_control) : "-"} sha=${sha(t)}`);
  });
}
console.log(`system: ${sysShape} total ${KB(sysBytes)} ~${tok(sysBytes)}tok`);

// ---- tools ----
const tools = Array.isArray(p.tools) ? p.tools : [];
const toolsJson = JSON.stringify(tools);
const toolsBytes = Buffer.byteLength(toolsJson);
console.log(`\ntools: ${tools.length} tools, ${KB(toolsBytes)} ~${tok(toolsBytes)}tok sha=${sha(toolsJson)}`);
console.log("  names:", tools.map(t => t.name).join(", "));
// cache_control on tools?
tools.forEach((t, i) => { if (t.cache_control) console.log(`  tools[${i}] ${t.name} cc=${JSON.stringify(t.cache_control)}`); });

// ---- messages ----
const msgs = Array.isArray(p.messages) ? p.messages : [];
console.log(`\nmessages: ${msgs.length}`);
let msgBytes = 0;
msgs.forEach((m, i) => {
  if (Array.isArray(m.content)) {
    m.content.forEach((b, j) => {
      const t = typeof b.text === "string" ? b.text : JSON.stringify(b);
      const bytes = Buffer.byteLength(t);
      msgBytes += bytes;
      const cc = b.cache_control ? JSON.stringify(b.cache_control) : "-";
      const preview = (b.type === "text" && typeof b.text === "string") ? b.text.slice(0, 50).replace(/\n/g, "\\n") : b.type;
      console.log(`  msg[${i}].${m.role}[${j}] ${b.type} ${KB(bytes)} ~${tok(bytes)}tok cc=${cc} sha=${sha(t)} | ${preview}`);
    });
  } else {
    const bytes = Buffer.byteLength(String(m.content));
    msgBytes += bytes;
    console.log(`  msg[${i}].${m.role} ${KB(bytes)} ~${tok(bytes)}tok | ${String(m.content).slice(0, 50)}`);
  }
});

const totalBytes = sysBytes + toolsBytes + msgBytes;
console.log(`\n=== TOTAL prefix: ${KB(totalBytes)} bytes ~${tok(totalBytes)} tokens (estimate @3.4 ch/tok) ===`);
console.log(`    tools ${tok(toolsBytes)} + system ${tok(sysBytes)} + messages ${tok(msgBytes)}`);

// count cache_control markers
let ccCount = 0;
for (const t of tools) if (t.cache_control) ccCount++;
if (Array.isArray(p.system)) for (const b of p.system) if (b.cache_control) ccCount++;
for (const m of msgs) if (Array.isArray(m.content)) for (const b of m.content) if (b.cache_control) ccCount++;
console.log(`cache_control markers: ${ccCount} (Anthropic max 4)`);

