import { createHash } from "node:crypto";
const sha = (s) => createHash("sha256").update(s).digest("hex").slice(0, 12);
const A = JSON.parse(readFileSync("/tmp/bridge-dump-A.json", "utf8"));
const B = JSON.parse(readFileSync("/tmp/bridge-dump-B.json", "utf8"));

function block(p, i, j) { return p.messages[i].content[j].text; }
const parts = [
  ["tools[]", JSON.stringify(A.tools), JSON.stringify(B.tools)],
  ["system[]", JSON.stringify(A.system), JSON.stringify(B.system)],
  ["msg0.block0 <system-context>", block(A,0,0), block(B,0,0)],
  ["msg0.block1 <project_context>", block(A,0,1), block(B,0,1)],
  ["msg1 Understood ack", JSON.stringify(A.messages[1]), JSON.stringify(B.messages[1])],
];
console.log("=== CROSS-SESSION BYTE-IDENTITY (session A vs session B, same cwd) ===");
let allMatch = true;
for (const [name, a, b] of parts) {
  const match = a === b;
  if (!match) allMatch = false;
  console.log(`${match ? "✓ IDENTICAL" : "✗ DIFFERS  "} ${name.padEnd(32)} A=${sha(a)} B=${sha(b)} (${Buffer.byteLength(a)}B)`);
}
// time-context (expected to match only within the same clock hour)
const tcA = block(A,2,0), tcB = block(B,2,0);
console.log(`${tcA===tcB?"✓ IDENTICAL":"~ varies   "} ${"msg2 time-context (hour-rounded)".padEnd(32)} A=${sha(tcA)} B=${sha(tcB)}`);
console.log(`\nCACHEABLE PREFIX (tools+system+block0+block1+ack) byte-identical across sessions: ${allMatch ? "YES ✓" : "NO ✗"}`);

// dump project_context for bloat inspection
writeFileSync("/tmp/project_context.txt", block(A,0,1));
console.log("\nwrote /tmp/project_context.txt for bloat inspection");

