function blocks(p){return {b0:p.messages[0].content[0].text, b1:p.messages[0].content[1].text, tools:JSON.stringify(p.tools)};}
const A=blocks(load("/tmp/bridge-dump-A.json")); // flag OFF
const C=blocks(load("/tmp/bridge-dump-C.json")); // flag ON
console.log("                       FLAG OFF (A)          FLAG ON (C)");
for(const k of ["b0","b1","tools"]){
  const a=A[k],c=C[k];
  console.log(`${k.padEnd(6)} ${(Buffer.byteLength(a)+"B ~"+tok(Buffer.byteLength(a))+"tok").padEnd(20)} ${(Buffer.byteLength(c)+"B ~"+tok(Buffer.byteLength(c))+"tok").padEnd(20)} sha ${sha(a)}->${sha(c)}`);
}
// does block0 (flag ON) now contain the global AGENTS chain + skills?
console.log("\nFLAG-ON block0 contains:");
for(const probe of ["# AGENTS.md","SOUL.md — Rusty","# How I Work","Pi Development — Map","available_skills","__PI_SYSTEM_PROMPT_DYNAMIC_BOUNDARY__"]){
  console.log(`  ${C.b0.includes(probe)?"YES":"no "}  ${probe}`);
}
console.log("\nFLAG-ON block1 (per-cwd tail) contains:");
for(const probe of ["# AGENTS.md","my-pi Agent Instructions","persistent","# Demo","Profile Memory Index"]){
  console.log(`  ${C.b1.includes(probe)?"YES":"no "}  ${probe}`);
}
'

