function setAdvisorToolState(pi: ExtensionAPI, enabled: boolean): void {
  const active = new Set(pi.getActiveTools());
  if (enabled) active.add("advisor");
  else active.delete("advisor");
  // setActiveTools rebuilds the system prompt and updates agent.state.tools.
  // No explicit refresh needed; pi.refreshTools is not part of the public ExtensionAPI.
  pi.setActiveTools([...active]);
}

