describe("extractor mutex + throttle", () => {
	function stubCtx(source: string = "interactive"): ExtensionContext {
		return {
			source,
			forkAgent: async () => {
				throw new Error("forkAgent should not be called in this test");
			},
			transcript: { append: () => {} },
		} as unknown as ExtensionContext;
	}
	test("memoryWrittenThisSession=true short-circuits without calling forkAgent", async () => {
		let turns = 10;
		let wrote = true;
		const ctx = stubCtx();
		const ex = createExtractor({
			slug: "t",
			originSessionId: "sid",
			getTurnCount: () => turns,
			memoryWrittenThisSession: () => wrote,
		});
		expect(await ex.maybeRun(ctx)).toEqual([]);
		expect(await ex.maybeRun(ctx)).toEqual([]); // still skipped after a direct write (mutex)
		wrote = false;
		turns = 1;
		// cursor was advanced to 10 by the mutex path, so newTurns < 0 — skip.
		expect(await ex.maybeRun(ctx)).toEqual([]);
	});
	test("missing forkAgent on ctx skips extraction gracefully", async () => {
		const ctxWithoutFork = {
			transcript: { append: () => {} },
		} as unknown as ExtensionContext;
		const turns = 10;
		const ex = createExtractor({
			slug: "t",
			originSessionId: "sid",
			getTurnCount: () => turns,
			memoryWrittenThisSession: () => false,
		});
		// Should return [] without throwing — guard handles missing forkAgent
		expect(await ex.maybeRun(ctxWithoutFork)).toEqual([]);
	});

	test("turn throttle skips fork below MIN_NEW_TURNS", async () => {
		const prev = process.env.PI_MEMORY_MIN_NEW_TURNS;
		process.env.PI_MEMORY_MIN_NEW_TURNS = "3";
		try {
			let turns = 1;
			const ctx = stubCtx(); // forkAgent throws if reached
			const ex = createExtractor({
				slug: "t",
				originSessionId: "sid",
				getTurnCount: () => turns,
				memoryWrittenThisSession: () => false,
			});
			expect(await ex.maybeRun(ctx)).toEqual([]);
			turns = 2;
			expect(await ex.maybeRun(ctx)).toEqual([]);
		} finally {
			if (prev === undefined) delete process.env.PI_MEMORY_MIN_NEW_TURNS;
			else process.env.PI_MEMORY_MIN_NEW_TURNS = prev;
		}
	});

	test("ctx.source === 'child-agent' short-circuits before fork — no recursion of extractor inside extractor's own child", async () => {
		const ctx = stubCtx("child-agent"); // throws if forkAgent is called
		expect(isMemorySubAgentCtx(ctx)).toBe(true);
		const ex = createExtractor({
			slug: "t",
			originSessionId: "sid",
			getTurnCount: () => 100, // way above the turn throttle
			memoryWrittenThisSession: () => false,
		});
		// Even with lots of new turns, the sub-agent guard must bail before fork.
		expect(await ex.maybeRun(ctx)).toEqual([]);
		expect(await ex.maybeRun(ctx)).toEqual([]);
	});

	test("isMemorySubAgentCtx() reads ctx.source", () => {
		expect(isMemorySubAgentCtx({ source: "interactive" })).toBe(false);
		expect(isMemorySubAgentCtx({ source: "rpc" })).toBe(false);
		expect(isMemorySubAgentCtx({ source: "extension" })).toBe(false);
		expect(isMemorySubAgentCtx({ source: "child-agent" })).toBe(true);
		expect(isMemorySubAgentCtx({})).toBe(false);
	});
});

