input.new_string:
function setAdvisorToolState(pi: ExtensionAPI, enabled: boolean): void {
  const current = pi.getActiveTools();
  const hasAdvisor = current.includes("advisor");
  // Cache stability: setActiveTools is NOT idempotent — every call emits a
  // tools_update event and a session write (pi-mono-fork agent-harness.ts), and
  // before_agent_start fires this every turn. Skip the call when the active set
  // is already what we want so the tools[] array stays byte-stable within a
  // session (mirrors tool-search's sameNames guard).
  if (enabled === hasAdvisor) return;
  const active = new Set(current);
  if (enabled) active.add("advisor");
  else active.delete("advisor");
  pi.setActiveTools([...active]);
}

