1	// pi extension: extend the cacheable BASE prompt with cwd-independent context.
2	//
3	// PROBLEM. pi-core inserts SYSTEM_PROMPT_DYNAMIC_BOUNDARY right before
4	// <project_context>, so the cache-stable base = just the pi harness prompt
5	// (~2.5k tokens). Everything else (global AGENTS chain + identity files +
6	// pi-dev.md, then cwd-specific AGENTS files, skills, date) lands in the dynamic
7	// tail. pi-ai splits the system prompt at the boundary; the claude-bridge keeps
8	// a cache marker on each side. So only the harness prompt is shared ACROSS
9	// cwds; the global agent instructions (identical in every repo) are re-cached
10	// per cwd.
11	//
12	// FIX. Relocate the boundary marker to sit AFTER the contiguous run of
13	// GLOBAL project_instructions blocks at the front of <project_context>. Those
14	// blocks (under ~/.pi/agent/ and ~/Projects/agent-scripts/) are byte-identical
15	// in every session/cwd, so moving them above the boundary makes them part of
16	// the shared base cache. cwd-derived blocks (~/Projects/AGENTS.md,
17	// <repo>/AGENTS.md), the skills registry, and the date stay in the dynamic tail.
18	//
19	// SAFETY. This is CONTENT-PRESERVING: the boundary marker is a non-semantic
20	// delimiter that pi-ai strips when splitting, so the text the model sees is
21	// byte-identical before and after relocation — only the cache split point
22	// moves. Recall therefore cannot regress (proven by the content-preservation
23	// test). The relocation only runs on a contiguous global PREFIX run, so an
24	// unexpected block ordering degrades to a no-op, never to data loss.
25	//
26	// CACHE. Deterministic + value-independent → the new base prefix is byte-stable
27	// across days and cwds. One-time cold start when first enabled.
28	//
29	// Gated OFF by default; enable with PI_EXTEND_BASE_PROMPT=1 after the eval
30	// (test.mjs) is green, per my-pi review guidelines for recall-affecting
31	// system-prompt changes.
32	
33	const BOUNDARY = "__PI_SYSTEM_PROMPT_DYNAMIC_BOUNDARY__";
34	
35	// Path prefixes whose project_instructions blocks are cwd-INDEPENDENT (the same
36	// in every session). Everything else stays in the dynamic tail.
37	const DEFAULT_GLOBAL_PREFIXES = [
38	  `${process.env.HOME || "/Users/luke"}/.pi/agent/`,
39	  `${process.env.HOME || "/Users/luke"}/Projects/agent-scripts/`,
40	];
41	
42	const PROJECT_INSTRUCTION_BLOCK =
43	  /<project_instructions path="([^"]+)">[\s\S]*?<\/project_instructions>/g;
44	
45	// Move the dynamic boundary to just after the leading contiguous run of global
46	// project_instructions blocks. Pure string transform; returns the input
47	// unchanged when there is nothing to move.
48	export function relocateBoundary(prompt, globalPrefixes = DEFAULT_GLOBAL_PREFIXES) {
49	  if (typeof prompt !== "string") return prompt;
50	  const bIdx = prompt.indexOf(BOUNDARY);
51	  if (bIdx === -1) return prompt;
52	
53	  const pcOpen = prompt.indexOf("<project_context>", bIdx);
54	  if (pcOpen === -1) return prompt;
55	
56	  const re = new RegExp(PROJECT_INSTRUCTION_BLOCK.source, "g");
57	  re.lastIndex = pcOpen;
58	  let lastGlobalEnd = -1;
59	  let expectedNextStart = -1;
60	  let match;
61	  while ((match = re.exec(prompt)) !== null) {
62	    // Contiguity guard: only an unbroken run from the first block counts. The
63	    // gap between blocks is whitespace; bail if a non-global block appears or
64	    // the run is interrupted by non-whitespace.
65	    if (expectedNextStart !== -1) {
66	      const gap = prompt.slice(expectedNextStart, match.index);
67	      if (gap.trim().length > 0) break;
68	    }
69	    const path = match[1];
70	    const isGlobal = globalPrefixes.some((p) => path.startsWith(p));
71	    if (!isGlobal) break;
72	    lastGlobalEnd = match.index + match[0].length;
73	    expectedNextStart = lastGlobalEnd;
74	  }
75	  if (lastGlobalEnd === -1) return prompt; // no global blocks at the front
76	
77	  // Remove the boundary (with its leading blank line) from its core position,
78	  // then re-insert it after the global run. Removal precedes the insertion
