// Resolve whether base-extension is enabled, across the config layers:
//   L4 (env, highest)  PI_EXTEND_BASE_PROMPT=1 forces on, =0 forces off.
//   L3 (settings.json) extensionConfig["cache-base-prompt"].extendBase.
//   default            off.
// Env is the escape hatch and always wins when set, per the L1-L4 model
// (L4 beats L3). The slice is read at filter-exec time, not registration.
export function isEnabled(pi) {
  const env = process.env.PI_EXTEND_BASE_PROMPT;
  if (env === "1") return true;
  if (env === "0") return false;
  const cfg = pi.getExtensionConfig?.("cache-base-prompt");
  return typeof cfg?.extendBase === "boolean" ? cfg.extendBase : false;
}

export default function cacheBasePromptExtension(pi) {
  // Always register; gate INSIDE the filter (read config at exec time) so the
  // registered filter set is deterministic. Disabled => identity, so the
  // system prompt — and its cache — is byte-identical when off.
  pi.hooks?.addFilter?.(
    "systemPrompt:build",
    "pi-cache-base-prompt.extend-base",
    (systemPrompt) => (isEnabled(pi) ? extendBase(systemPrompt) : systemPrompt),
    // Run AFTER content-rewriting filters (skill-loader=20) so the boundary
    // lands relative to the final block layout.
    { priority: 90 },
  );
}

export const __test__ = { BOUNDARY, DEFAULT_GLOBAL_PREFIXES, relocateBoundary, extendBase, isEnabled };

