// pi extension: extend the cacheable BASE prompt with cwd-independent context.
//
// PROBLEM. pi-core inserts SYSTEM_PROMPT_DYNAMIC_BOUNDARY right before
// <project_context>, so the cache-stable base = just the pi harness prompt
// (~2.5k tokens). Everything else (global AGENTS chain + identity files +
// pi-dev.md, then cwd-specific AGENTS files, skills, date) lands in the dynamic
// tail. pi-ai splits the system prompt at the boundary; the claude-bridge keeps
// a cache marker on each side. So only the harness prompt is shared ACROSS
// cwds; the global agent instructions (identical in every repo) are re-cached
// per cwd.
//
// FIX. Relocate the boundary marker to sit AFTER the contiguous run of
// GLOBAL project_instructions blocks at the front of <project_context>. Those
// blocks (under ~/.pi/agent/ and ~/Projects/agent-scripts/) are byte-identical
// in every session/cwd, so moving them above the boundary makes them part of
// the shared base cache. cwd-derived blocks (~/Projects/AGENTS.md,
// <repo>/AGENTS.md), the skills registry, and the date stay in the dynamic tail.
//
// SAFETY. This is CONTENT-PRESERVING: the boundary marker is a non-semantic
// delimiter that pi-ai strips when splitting, so the text the model sees is
// byte-identical before and after relocation — only the cache split point
// moves. Recall therefore cannot regress (proven by the content-preservation
// test). The relocation only runs on a contiguous global PREFIX run, so an
// unexpected block ordering degrades to a no-op, never to data loss.
//
// CACHE. Deterministic + value-independent → the new base prefix is byte-stable
// across days and cwds. One-time cold start when first enabled.
//
// Gated OFF by default; enable with PI_EXTEND_BASE_PROMPT=1 after the eval
// (test.mjs) is green, per my-pi review guidelines for recall-affecting
// system-prompt changes.

const BOUNDARY = "__PI_SYSTEM_PROMPT_DYNAMIC_BOUNDARY__";

// Path prefixes whose project_instructions blocks are cwd-INDEPENDENT (the same
// in every session). Everything else stays in the dynamic tail.
const DEFAULT_GLOBAL_PREFIXES = [
  `${process.env.HOME || "/Users/luke"}/.pi/agent/`,
  `${process.env.HOME || "/Users/luke"}/Projects/agent-scripts/`,
];

const PROJECT_INSTRUCTION_BLOCK =
  /<project_instructions path="([^"]+)">[\s\S]*?<\/project_instructions>/g;

// Move the dynamic boundary to just after the leading contiguous run of global
// project_instructions blocks. Pure string transform; returns the input
// unchanged when there is nothing to move.
export function relocateBoundary(prompt, globalPrefixes = DEFAULT_GLOBAL_PREFIXES) {
  if (typeof prompt !== "string") return prompt;
  const bIdx = prompt.indexOf(BOUNDARY);
  if (bIdx === -1) return prompt;

  const pcOpen = prompt.indexOf("<project_context>", bIdx);
  if (pcOpen === -1) return prompt;

  const re = new RegExp(PROJECT_INSTRUCTION_BLOCK.source, "g");
  re.lastIndex = pcOpen;
  let lastGlobalEnd = -1;
  let expectedNextStart = -1;
  let match;
  while ((match = re.exec(prompt)) !== null) {
    // Contiguity guard: only an unbroken run from the first block counts. The
    // gap between blocks is whitespace; bail if a non-global block appears or
    // the run is interrupted by non-whitespace.
    if (expectedNextStart !== -1) {
      const gap = prompt.slice(expectedNextStart, match.index);
      if (gap.trim().length > 0) break;
    }
    const path = match[1];
    const isGlobal = globalPrefixes.some((p) => path.startsWith(p));
    if (!isGlobal) break;
    lastGlobalEnd = match.index + match[0].length;
    expectedNextStart = lastGlobalEnd;
  }
  if (lastGlobalEnd === -1) return prompt; // no global blocks at the front

  // Remove the boundary (with its leading blank line) from its core position,
  // then re-insert it after the global run. Removal precedes the insertion
  // point, so shift the target left by the removed length.
  const removeStart = prompt.startsWith(`\n\n${BOUNDARY}`, bIdx - 2) ? bIdx - 2 : bIdx;
  const removeLen = bIdx + BOUNDARY.length - removeStart;
  const without = prompt.slice(0, removeStart) + prompt.slice(removeStart + removeLen);
  const insertAt = lastGlobalEnd - removeLen;
  return without.slice(0, insertAt) + `\n\n${BOUNDARY}` + without.slice(insertAt);
}

const PC_OPEN = "<project_context>";
const PC_CLOSE = "</project_context>";
const SKILLS_PREAMBLE = "The following skills";
const SKILLS_END = "</available_skills>";

// Multiset of project_instructions paths, used by the fail-safe self-check.
function blockPaths(s) {
  return [...s.matchAll(/<project_instructions path="([^"]+)">/g)].map((m) => m[1]).sort();
}
function sameContent(a, b) {
  const pa = blockPaths(a).join("\n");
  const pb = blockPaths(b).join("\n");
  if (pa !== pb) return false;
  if (a.includes(SKILLS_END) !== b.includes(SKILLS_END)) return false;
  if (a.includes("Current date:") !== b.includes("Current date:")) return false;
  return true;
}

// Stronger transform: in addition to relocating the boundary after the global
// AGENTS run, pull the (cwd-independent) skills registry above the boundary by
// splitting <project_context> into a global section (kept in place, with skills)
// and a cwd section (moved below the boundary). One semantic change: the skills
// registry now precedes the cwd-specific AGENTS files. Falls back to
// relocateBoundary when the skills block is absent, and self-checks content
// (returns the input unchanged if the block multiset would differ).
export function extendBase(prompt, globalPrefixes = DEFAULT_GLOBAL_PREFIXES) {
  if (typeof prompt !== "string") return prompt;
  const bIdx = prompt.indexOf(BOUNDARY);
  if (bIdx === -1) return prompt;
  const pcOpen = prompt.indexOf(PC_OPEN, bIdx);
  const pcClose = prompt.indexOf(PC_CLOSE, pcOpen);
  if (pcOpen === -1 || pcClose === -1) return prompt;
  const pcCloseEnd = pcClose + PC_CLOSE.length;

  const sIdx = prompt.indexOf(SKILLS_PREAMBLE, pcCloseEnd);
  const availEnd0 = prompt.indexOf(SKILLS_END, sIdx);
  if (sIdx === -1 || availEnd0 === -1) return relocateBoundary(prompt, globalPrefixes);
  const availEnd = availEnd0 + SKILLS_END.length;

  // Find the end of the leading contiguous global run inside project_context.
  const re = new RegExp(PROJECT_INSTRUCTION_BLOCK.source, "g");
  re.lastIndex = pcOpen + PC_OPEN.length;
  let gEnd = -1;
  let expectedNextStart = -1;
  let match;
  while ((match = re.exec(prompt)) !== null && match.index < pcClose) {
    if (expectedNextStart !== -1 && prompt.slice(expectedNextStart, match.index).trim().length > 0) break;
    if (!globalPrefixes.some((p) => match[1].startsWith(p))) break;
    gEnd = match.index + match[0].length;
    expectedNextStart = gEnd;
  }
  if (gEnd === -1) return prompt; // no global blocks at the front

  const removeStart = prompt.startsWith(`\n\n${BOUNDARY}`, bIdx - 2) ? bIdx - 2 : bIdx;
  const harness = prompt.slice(0, removeStart);
  const globalPc = prompt.slice(pcOpen, gEnd); // "<project_context>...intro...global blocks"
  const cwdInner = prompt.slice(gEnd, pcClose); // remaining cwd blocks (no tags)
  const between = prompt.slice(pcCloseEnd, sIdx); // whitespace before skills
  const skills = prompt.slice(sIdx, availEnd);
  const afterSkills = prompt.slice(availEnd); // date + cwd line (dynamic)

  const hasCwd = cwdInner.trim().length > 0;
  const result = hasCwd
    ? `${harness}${globalPc}\n${PC_CLOSE}${between}${skills}\n\n${BOUNDARY}\n\n${PC_OPEN}${cwdInner}\n${PC_CLOSE}${afterSkills}`
    : `${harness}${globalPc}\n${PC_CLOSE}${between}${skills}\n\n${BOUNDARY}${afterSkills}`;

  return sameContent(result, prompt) ? result : prompt;
}

export default function cacheBasePromptExtension(pi) {
  if (process.env.PI_EXTEND_BASE_PROMPT !== "1") return;
  pi.hooks?.addFilter?.(
    "systemPrompt:build",
    "pi-cache-base-prompt.extend-base",
    (systemPrompt) => extendBase(systemPrompt),
    // Run AFTER content-rewriting filters (skill-loader=20) so the boundary
    // lands relative to the final block layout.
    { priority: 90 },
  );
}

export const __test__ = { BOUNDARY, DEFAULT_GLOBAL_PREFIXES, relocateBoundary, extendBase };

