// Eval for cache-base-prompt: relocating the dynamic boundary must be
// CONTENT-PRESERVING (recall cannot regress) and must move the cache split to
// after the contiguous global project_instructions run.

import assert from "node:assert/strict";
import { __test__ } from "./index.mjs";

const { BOUNDARY, relocateBoundary, extendBase } = __test__;
const PREFIXES = ["/Users/luke/.pi/agent/", "/Users/luke/Projects/agent-scripts/"];

toolUseResult.originalFile:
// Eval for cache-base-prompt: relocating the dynamic boundary must be
// CONTENT-PRESERVING (recall cannot regress) and must move the cache split to
// after the contiguous global project_instructions run.

import assert from "node:assert/strict";
import { __test__ } from "./index.mjs";

const { BOUNDARY, relocateBoundary, extendBase } = __test__;
const PREFIXES = ["/Users/luke/.pi/agent/", "/Users/luke/Projects/agent-scripts/"];

const block = (path, body) =>
  `<project_instructions path="${path}">\n${body}\n</project_instructions>`;

const HARNESS = "You are an expert coding assistant.\nGuidelines:\n- be terse";
const PC =
  "<project_context>\n\nProject-specific instructions and guidelines:\n\n" +
  block("/Users/luke/.pi/agent/AGENTS.md", "global harness rules") +
  "\n\n" +
  block("/Users/luke/Projects/agent-scripts/AGENTS.md", "global agent base") +
  "\n\n" +
  block("/Users/luke/Projects/agent-scripts/SOUL.md", "soul") +
  "\n\n" +
  block("/Users/luke/.pi/agent/pi-dev.md", "pi dev map") +
  "\n\n" +
  block("/Users/luke/Projects/AGENTS.md", "cwd: projects index") +
  "\n\n" +
  block("/Users/luke/Projects/personal/my-pi/AGENTS.md", "cwd: my-pi") +
  "\n\n</project_context>\n";
const SKILLS = "\n\nThe following skills...\n<available_skills>\n- foo\n</available_skills>";
const TAIL = "\nCurrent date: 2026-05-29\nCurrent working directory: /Users/luke/Projects/personal/my-pi";

const original = `${HARNESS}\n\n${BOUNDARY}\n\n${PC}${SKILLS}${TAIL}`;

// Strip the boundary delimiter (and its leading blank line) for content compare.
const stripBoundary = (s) => s.split(`\n\n${BOUNDARY}`).join("").split(BOUNDARY).join("");

const result = relocateBoundary(original, PREFIXES);

// 1. CONTENT PRESERVATION — the only thing that changed is the delimiter
// position. This is the recall guarantee.
assert.equal(stripBoundary(result), stripBoundary(original), "relocation is content-preserving (recall cannot regress)");

// 2. Boundary moved: exactly one boundary, after the global run.
assert.equal(result.split(BOUNDARY).length - 1, 1, "exactly one boundary marker remains");
const bIdx = result.indexOf(BOUNDARY);
const stable = result.slice(0, bIdx);
const dynamic = result.slice(bIdx + BOUNDARY.length);

// 3. Stable (base) side carries harness + all global blocks.
assert.ok(stable.includes(HARNESS), "harness prompt stays in base");
assert.ok(stable.includes('path="/Users/luke/.pi/agent/AGENTS.md"'), "global agent AGENTS.md moved into base");
assert.ok(stable.includes('path="/Users/luke/Projects/agent-scripts/AGENTS.md"') && stable.includes('path="/Users/luke/Projects/agent-scripts/SOUL.md"'), "agent-scripts chain moved into base");
assert.ok(stable.includes('path="/Users/luke/.pi/agent/pi-dev.md"'), "pi-dev.md moved into base");

// 4. Dynamic side keeps cwd-specific blocks, skills, date.
assert.ok(dynamic.includes('path="/Users/luke/Projects/AGENTS.md"'), "cwd Projects/AGENTS.md stays dynamic");
assert.ok(dynamic.includes('path="/Users/luke/Projects/personal/my-pi/AGENTS.md"'), "cwd my-pi AGENTS.md stays dynamic");
assert.ok(dynamic.includes("<available_skills>"), "skills stay dynamic");
assert.ok(dynamic.includes("Current date: 2026-05-29"), "date stays dynamic");

// 5. Global blocks are NOT duplicated into the dynamic side.
assert.ok(!dynamic.includes("global harness rules"), "no global content leaked into dynamic side");

// 6. Idempotent — a second pass is a no-op (boundary now precedes project_context).
assert.equal(relocateBoundary(result, PREFIXES), result, "second pass is a no-op (idempotent)");

// 7. No-op guards.
assert.equal(relocateBoundary("no boundary here", PREFIXES), "no boundary here", "no boundary => unchanged");
const noGlobal = `${HARNESS}\n\n${BOUNDARY}\n\n<project_context>\n\n${block("/Users/luke/Projects/AGENTS.md", "x")}\n\n</project_context>\n`;
assert.equal(relocateBoundary(noGlobal, PREFIXES), noGlobal, "no global blocks at front => unchanged");

// 8. Contiguity guard: a cwd block before a global block stops the run early.
const interleaved = `${HARNESS}\n\n${BOUNDARY}\n\n<project_context>\n\n${block("/Users/luke/Projects/AGENTS.md", "cwd first")}\n\n${block("/Users/luke/.pi/agent/AGENTS.md", "global second")}\n\n</project_context>\n`;
assert.equal(relocateBoundary(interleaved, PREFIXES), interleaved, "non-global first block => no relocation");

// ---- extendBase: skills pulled above the boundary, cwd split out ----
{
  const r = extendBase(original, PREFIXES);
  // content multiset preserved (same blocks + skills + date)
  const paths = (s) => [...s.matchAll(/<project_instructions path="([^"]+)">/g)].map((m) => m[1]).sort().join(",");
  assert.equal(paths(r), paths(original), "extendBase preserves the project_instructions multiset");
  assert.ok(r.includes("<available_skills>") && r.includes("Current date: 2026-05-29"), "skills + date still present");

  const bi = r.indexOf(BOUNDARY);
  assert.equal(r.split(BOUNDARY).length - 1, 1, "exactly one boundary");
  const stable = r.slice(0, bi);
  const dynamic = r.slice(bi + BOUNDARY.length);

  // skills + global AGENTS now in the base; cwd AGENTS + date in the tail.
  assert.ok(stable.includes("<available_skills>"), "skills moved into base");
  assert.ok(stable.includes('path="/Users/luke/.pi/agent/pi-dev.md"'), "global blocks in base");
  assert.ok(dynamic.includes('path="/Users/luke/Projects/personal/my-pi/AGENTS.md"'), "cwd AGENTS stay dynamic");
  assert.ok(dynamic.includes("Current date: 2026-05-29"), "date stays dynamic");
  assert.ok(!stable.includes("cwd: my-pi"), "no cwd content leaked into base");

  // two valid project_context sections (global + cwd), balanced tags.
  assert.equal(r.split("<project_context>").length - 1, 2, "two project_context opens");
  assert.equal(r.split("</project_context>").length - 1, 2, "two project_context closes");

  // fall back to relocateBoundary when there is no skills block.
  const noSkills = `${HARNESS}\n\n${BOUNDARY}\n\n${PC}${TAIL}`;
  assert.equal(extendBase(noSkills, PREFIXES), relocateBoundary(noSkills, PREFIXES), "no skills => falls back to relocateBoundary");
}

console.log("ok — cache-base-prompt relocation + skills extension are content-preserving and correct");

