// ---- config layering: L4 env overrides L3 settings; default off ----
{
  const prevEnv = process.env.PI_EXTEND_BASE_PROMPT;
  const piWith = (cfg) => ({ getExtensionConfig: (ns) => (ns === "cache-base-prompt" ? cfg : undefined) });

  delete process.env.PI_EXTEND_BASE_PROMPT;
  assert.equal(isEnabled(piWith(undefined)), false, "default off: no env, no setting");
  assert.equal(isEnabled(piWith({ extendBase: true })), true, "L3 on: settings.extendBase=true");
  assert.equal(isEnabled(piWith({ extendBase: false })), false, "L3 off: settings.extendBase=false");
  assert.equal(isEnabled({}), false, "no getExtensionConfig accessor => off");

  process.env.PI_EXTEND_BASE_PROMPT = "1";
  assert.equal(isEnabled(piWith({ extendBase: false })), true, "L4 override on: env=1 beats L3 false");
  process.env.PI_EXTEND_BASE_PROMPT = "0";
  assert.equal(isEnabled(piWith({ extendBase: true })), false, "L4 override off: env=0 beats L3 true");

  if (prevEnv === undefined) delete process.env.PI_EXTEND_BASE_PROMPT;
  else process.env.PI_EXTEND_BASE_PROMPT = prevEnv;
}

// ---- default export: filter always registers, gates inside (identity when off) ----
{
  const prevEnv = process.env.PI_EXTEND_BASE_PROMPT;
  delete process.env.PI_EXTEND_BASE_PROMPT;
  const mod = await import("./index.mjs");

  let registered = null;
  const makePi = (cfg) => ({
    getExtensionConfig: () => cfg,
    hooks: { addFilter: (event, id, fn) => { registered = { event, id, fn }; } },
  });

  // Disabled (no env, no setting): filter registers but is identity.
  registered = null;
  mod.default(makePi(undefined));
  assert.ok(registered, "filter is registered even when disabled (deterministic filter set)");
  assert.equal(registered.event, "systemPrompt:build", "registers on systemPrompt:build");
  const sample = `${HARNESS}\n\n${BOUNDARY}\n\n${PC}\n${SKILLS}\n${TAIL}`;
  assert.equal(registered.fn(sample), sample, "disabled => identity (byte-identical, cache-safe)");

  // Enabled via L3: filter transforms.
  registered = null;
  mod.default(makePi({ extendBase: true }));
  assert.equal(registered.fn(sample), extendBase(sample), "enabled via L3 => extendBase transform");

  if (prevEnv === undefined) delete process.env.PI_EXTEND_BASE_PROMPT;
  else process.env.PI_EXTEND_BASE_PROMPT = prevEnv;
}

console.log("ok — cache-base-prompt relocation + skills extension are content-preserving and correct");

